insert into woerter (slug, wort, artikel, ipa, wortart, kategorie, definition, bedeutungen, beispiel) values
  ('aufgeklaeata-absolutismus', 'Aufgekläata Absolutismus', '', '', '', '', 'Aufgeklärter Absolutismus', '[{"kategorie": "hist.", "text": "\"Regierungsform, die im 18. Jahrhundert in Europa aufkam und in der Herrscher ihre absolute Macht beibehielten, aber gleichzeitig Reformen im Sinne der [[Aufklärung]] einführten\""}, {"kategorie": "", "text": "Diese Herrscher nutzten ihre Macht, um Vernunft, Bildung, wirtschaftlichen Fortschritt und soziale Gerechtigkeit zu fördern, ohne jedoch ihre monarchische Autorität aufzugeben"}, {"kategorie": "", "text": "Merkmale des aufgeklärten Absolutismus: (i) Reformbereitschaft (die Monarchen führten Reformen ein, die auf den Ideen der Aufklärung basierten, wie religiöse Toleranz, Bildungsförderung und Rechtsstaatlichkeit), (ii) zentralisierte Macht (trotz der Reformen blieb die Macht stark in den Händen des Monarchen, der die Reformen \"von oben\" umsetzte, oft ohne parlamentarische oder demokratische Beteiligung), (iii) Fokus auf das Gemeinwohl (aufgeklärte Absolutisten sahen sich als Diener des Staates und handelten im Interesse des Allgemeinwohls, jedoch immer unter der Voraussetzung ihrer absoluten Macht), (iv) Pragmatismus (diese Herrscher setzten Reformen um, die den Staat effizienter und wirtschaftlich stärker machen sollten, waren aber vorsichtig, die eigene Machtbasis nicht zu gefährden)"}, {"kategorie": "", "text": "In Wien fand der aufgeklärte Absolutismus seinen prominentesten Vertreter in Kaiser [[Joseph]] II. (regierte von 1765 bis 1790), der gemeinsam mit seiner Mutter [[Maria]] Theresia (regierte von 1740 bis 1780) die [[Habsburgermonarchie]] prägte. Joseph II. setzte viele Reformen um, die die Ideen der Aufklärung widerspiegelten, und wird oft als Musterbeispiel eines aufgeklärten Absolutisten genannt"}, {"kategorie": "", "text": "Josephinische Reformen: (i) Religionspolitik (Joseph II. führte das [[Toleranzpatent]] von 1781 ein, das religiöse Minderheiten wie Protestanten und Juden mehr Rechte gewährte. Gleichzeitig beschränkte er den Einfluss der katholischen Kirche, schloss viele Klöster und förderte eine stärker staatlich kontrollierte Kirche), (ii) Bildungsreformen (Joseph förderte den Aufbau eines staatlich kontrollierten Bildungssystems. Er ließ Schulen gründen, um die allgemeine Bevölkerung zu bilden und den Analphabetismus zu verringern), (iii) Justizreformen (es wurden Gesetze geschaffen, die den Strafvollzug humaner machten. Unter Joseph II. wurde die Folter abgeschafft und das Todesurteil in den meisten Fällen durch mildere Strafen ersetzt), (iv) soziale Reformen (Joseph führte eine Lockerung der Zensur und Maßnahmen zur Verbesserung der Lebensbedingungen der Bauern ein, darunter die Abschaffung der Leibeigenschaft)"}, {"kategorie": "", "text": "Obwohl Joseph II. viele progressive Reformen einführte, stießen diese nicht immer auf Akzeptanz. Vor allem der Adel und die Kirche wehrten sich gegen den Verlust von Privilegien. Nach Josephs Tod wurden viele seiner Reformen teilweise zurückgenommen, da sie auf Widerstand in der Bevölkerung und beim Adel stießen."}]'::jsonb, ''),
  ('toleranzpatent-von-1781', 'Toleranzpatent von 1781', '', '', '', '', 'Toleranzpatent von 1781', '[{"kategorie": "", "text": "Es gewährte nicht-katholischen Christen, insbesondere Protestanten (Lutheranern und Calvinisten) sowie den Orthodoxen, gewisse Rechte zur Ausübung ihrer Religion"}, {"kategorie": "", "text": "Obwohl die katholische Kirche weiterhin die vorherrschende Religion blieb, bedeutete das Toleranzpatent einen wichtigen Schritt in Richtung religiöser Freiheit und mehr Gleichberechtigung"}, {"kategorie": "", "text": "Hauptinhalte des Toleranzpatents: (i) religiöse Duldung (Protestanten, Orthodoxe und andere christliche Minderheiten durften ihre Religion unter bestimmten Bedingungen ausüben, ohne dabei staatliche Diskriminierung zu erfahren. Diese Duldung bezog sich vor allem auf den privaten und häuslichen Bereich), (ii) Rechte der Nichtkatholiken (die Angehörigen dieser Minderheiten erhielten das Recht auf private Religionsausübung, jedoch keine völlige Gleichberechtigung im öffentlichen Raum. Ihre Kirchen durften gebaut werden, allerdings nur ohne Türme und Glocken. Sie durften ihre eigenen Schulen betreiben und hatten eingeschränkten Zugang zu öffentlichen Ämtern), (iii) zivile Rechte (neben der religiösen Toleranz brachte das Patent auch Verbesserungen in den zivilen Rechten für Nichtkatholiken. Sie durften Gewerbe ausüben und an staatlichen Universitäten studieren, was zuvor oft eingeschränkt war)"}, {"kategorie": "", "text": "Das Toleranzpatent war ein bedeutender Schritt im Kontext der [[Aufklärung]] und des [[aufgeklärten]] Absolutismus in der [[Habsburgermonarchie]]. Es sollte die religiösen Spannungen entschärfen und zur wirtschaftlichen und sozialen Stabilität beitragen. Das Patent galt jedoch nicht für Juden, die erst später unter Joseph II. durch das [[Judenpatent]] von 1782 ähnliche Rechte erhielten"}, {"kategorie": "", "text": "Insgesamt war das Toleranzpatent von 1781 ein bedeutendes Reformwerk, das die religiöse Vielfalt in der Habsburgermonarchie anerkannte und den Grundstein für eine weitergehende Liberalisierung und Modernisierung des Staates legte."}]'::jsonb, ''),
  ('juudnpatent-von-1782', 'Juudnpatent von 1782', '', '', '', '', 'Judenpatent von 1782', '[{"kategorie": "allg.", "text": "\"Gesetz, das von Kaiser [[Joseph]] II. im Rahmen seiner Reformen erlassen wurde, um die Lebensbedingungen der jüdischen Bevölkerung in der [[Habsburgermonarchie]] zu verbessern und sie stärker in die Gesellschaft zu integrieren\""}, {"kategorie": "", "text": "Es gewährte den Juden bestimmte Rechte, jedoch unter der Prämisse der staatlichen Kontrolle und Angleichung an die christliche Mehrheitsgesellschaft"}, {"kategorie": "", "text": "Das Judenpatent war Teil der aufklärerischen Reformen des [[aufgeklärten]] Absolutismus, zielte jedoch nicht auf vollständige Gleichstellung ab"}, {"kategorie": "", "text": "Hauptinhalte des Judenpatents: (i) Erweiterung der bürgerlichen Rechte (Juden erhielten das Recht, einige Berufe auszuüben, die ihnen vorher verschlossen waren, und durften an staatlichen Schulen und Universitäten studieren. Sie durften Fabriken und Manufakturen betreiben, was ihnen ökonomische Freiheiten und Aufstiegsmöglichkeiten verschaffte), (ii) Einschränkung der Selbstverwaltung (das Patent zielte darauf ab, jüdische Institutionen und die Selbstverwaltung der jüdischen Gemeinden einzuschränken und stärker unter staatliche Kontrolle zu bringen. Der Gebrauch von Jiddisch und Hebräisch in offiziellen Angelegenheiten wurde verboten, um die Assimilation der Juden in die Mehrheitsgesellschaft zu fördern), (iii) Pflicht zur Bildung und Militärdienst (eEs wurde eine Schulpflicht für jüdische Kinder eingeführt, die nun auch staatliche Schulen besuchen mussten. Ziel war es, die Bildung zu verbessern und die Integration in die Gesellschaft zu fördern. Juden wurden zum Militärdienst verpflichtet, was in der damaligen Zeit eine ungewöhnliche Maßnahme war, da sie zuvor oft von solchen Pflichten ausgenommen waren, (iv) Abschaffung diskriminierender Vorschriften (das Judenpatent hob einige diskriminierende Gesetze auf, wie zum Beispiel das Tragen spezieller Kleidung oder die Zahlung von Sondersteuern, die Juden in vielen Teilen der Monarchie auferlegt worden waren)"}, {"kategorie": "", "text": "Trotz der Erweiterung bestimmter Rechte gab es auch erhebliche Einschränkungen. Juden wurden weiterhin sozial und rechtlich benachteiligt. Sie durften keine öffentlichen Ämter bekleiden, und ihr Zugang zu bestimmten Berufen blieb eingeschränkt. Zudem sollten sie sich kulturell und sprachlich der christlichen Mehrheitsgesellschaft anpassen. In diesem Sinne spiegelt das Judenpatent die ambivalente Haltung des [[aufgeklärten]] Absolutismus wider, der Reformen umsetzte, aber die gesellschaftliche Hierarchie nicht vollständig infrage stellte."}]'::jsonb, ''),
  ('josefinische-refoaman', 'Josefinische Refoaman', '', '', '', '', 'Josefinische Reformen', '[{"kategorie": "hist.", "text": "\"eine umfassende Reihe von politischen, sozialen und wirtschaftlichen Maßnahmen, die unter Kaiser [[Joseph]] II. (regierte von 1765 bis 1790) in der [[Habsburgermonarchie]] umgesetzt wurden\""}, {"kategorie": "", "text": "Diese Reformen basierten auf den Idealen der [[Aufklärung]] und des [[aufgeklärten]] Absolutismus und zielten darauf ab, den Staat zu modernisieren, die Macht der Kirche zu begrenzen und das Wohl der Bevölkerung zu verbessern"}, {"kategorie": "", "text": "Joseph II. verfolgte dabei das Ziel, den Staat effizienter, rationaler und humaner zu gestalten, ohne jedoch die monarchische Autorität infrage zu stellen"}, {"kategorie": "", "text": "Wichtige Josefinische Reformen: (i) Religiöse Reformen ([[Toleranzpatent]] von 1781: Gewährung religiöser Toleranz für Protestanten, Orthodoxe und Juden. Dies ermöglichte es diesen Gruppen, ihre Religion auszuüben, Schulen zu gründen und eingeschränkten Zugang zu öffentlichen Ämtern zu erhalten), (ii) Säkularisierung (Joseph II. löste viele Klöster auf, die keine sozialen Aufgaben wie Bildung oder Krankenpflege erfüllten, und verwendete deren Vermögen für staatliche Zwecke. Die staatliche Kontrolle über die Kirche wurde verstärkt, und die Zahl der kirchlichen Feiertage reduziert), (iii) soziale und rechtliche Reformen (Abschaffung der Leibeigenschaft: Die Leibeigenschaft der Bauern wurde gelockert, wodurch diese mehr Freiheiten erhielten. Sie durften ihren Wohnort wechseln und waren nicht mehr vollständig von ihren Grundherren abhängig), (iv) Justizreformen (Joseph II. schaffte die Folter ab, führte humanere Strafen ein und förderte die Idee der Gleichheit vor dem Gesetz. Auch die Todesstrafe wurde weitgehend abgeschafft), (v) Bildung und Gesundheitswesen (Schulpflicht: Joseph führte die allgemeine Schulpflicht ein und förderte den Ausbau eines staatlichen Bildungssystems, um die Alphabetisierung und Bildung der Bevölkerung zu verbessern), (vi) Krankenversorgung (der Kaiser ließ Krankenhäuser und Pflegeeinrichtungen ausbauen, darunter das berühmte [[Allgemeine]] Krankenhaus in Wien, das zu seiner Zeit eines der modernsten in Europa war), (vi) wirtschaftliche Reformen (Handels- und Steuerreformen: Joseph II. förderte den freien Handel und versuchte, das Zunftwesen zu lockern, um die wirtschaftliche Entwicklung zu stimulieren. Er führte ein einheitliches Steuersystem ein, um die Belastungen gerechter zu verteilen), (vii) Agrarreformen (durch Maßnahmen wie die Abschaffung der Leibeigenschaft und die Förderung der Landwirtschaft versuchte Joseph, die Produktivität zu steigern und das bäuerliche Leben zu verbessern), (viii) Verwaltungsreformen (Zentralisierung der Verwaltung: Joseph führte eine straffe, zentralisierte Verwaltung ein, die die Macht des Kaisers stärken und die Bürokratie effizienter machen sollte. Dazu gehörte die Einführung einer einheitlichen Amtssprache (Deutsch) und die Vereinheitlichung der Verwaltung in den [[Kronländern]])"}, {"kategorie": "", "text": "Die Josefinischen Reformen führten zu weitreichenden Veränderungen in der Habsburgermonarchie und prägten den Staat nachhaltig. Allerdings stieß Josephs Reformprogramm auf erheblichen Widerstand, besonders seitens des Adels, der Kirche und der ländlichen Bevölkerung. Viele Reformen waren zu radikal und wurden nach seinem Tod 1790 teilweise zurückgenommen. Dennoch legten sie den Grundstein für die Modernisierung der Habsburgermonarchie und beeinflussten zukünftige Entwicklungen."}]'::jsonb, ''),
  ('wiina-hof', 'Wiina Hof', '', '', '', '', 'Wiener Hof', '[{"kategorie": "hist.", "text": "\"kaiserlicher Hof der [[Habsburger]] in Wien, der vom späten Mittelalter bis zum Ende der Monarchie 1918 das politische, kulturelle und gesellschaftliche Zentrum der [[Habsburgermonarchie]] und des [[Heiligen]] Römischen Reiches darstellte\""}, {"kategorie": "", "text": "Der Begriff umfasst sowohl den Sitz der habsburgischen Herrscher als auch den gesamten höfischen Apparat, der aus Adeligen, Beamten, Künstlern und anderen Höflingen bestand"}, {"kategorie": "", "text": "Merkmale des Wiener Hofs: (i) politisches Zentrum (der Wiener Hof war der Sitz der [[Habsburger]] Dynastie, die über das [[Heilige]] Römische Reich und später über die [[österreichischen]] Erblande und das [[Kaisertum]] Österreich herrschte. Hier wurden wichtige Entscheidungen in Politik, Diplomatie und Verwaltung getroffen), (ii) Residenz (die Hauptresidenz des Wiener Hofs war die [[Hofburg]], die im Zentrum Wiens liegt. Auch das [[Schloss]] Schönbrunn diente als Sommerresidenz und war ein wichtiger Schauplatz des höfischen Lebens), (iii) gesellschaftliches und kulturelles Zentrum (der Wiener Hof war nicht nur politisch wichtig, sondern auch ein Zentrum der Kultur und des gesellschaftlichen Lebens. Adel und Künstler verkehrten hier, und die Hofmusik und das Theater blühten unter kaiserlicher Förderung. Berühmte Komponisten wie Joseph Haydn, Wolfgang Amadeus Mozart und Ludwig van Beethoven wirkten zeitweise am Wiener Hof), (iv) höfische Etikette und Prunk (der Wiener Hof war bekannt für seine strenge Etikette und seine Prachtentfaltung. Große Feste, Bälle und Jagden waren fester Bestandteil des höfischen Lebens, und die Architektur der Hofburg und anderer Paläste spiegelte den Glanz und die Macht der Habsburger wider), (v) Verwaltungszentrum (neben der Funktion als Residenz war der Wiener Hof das Zentrum der habsburgischen Bürokratie. Von hier aus wurde die Verwaltung des riesigen Habsburgerreichs organisiert, einschließlich der verschiedenen [[Kronländer]])"}, {"kategorie": "", "text": "Der Wiener Hof war das politische, gesellschaftliche und kulturelle Zentrum der Habsburgermonarchie und prägte Wien über Jahrhunderte hinweg. Mit seiner Kombination aus Macht, Prachtentfaltung und kultureller Förderung war der Wiener Hof nicht nur für die Geschichte Österreichs, sondern für ganz Europa von zentraler Bedeutung."}]'::jsonb, ''),
  ('oestarreichische-eablaunde', 'Östarreichische Eablaunde', '', '', '', '', 'Österreichische Erblande', '[{"kategorie": "hist.", "text": "\"jene Territorien, die sich im Besitz der [[Habsburger]] Dynastie befanden und die sie durch Erbschaft, Heirat oder Verträge dauerhaft in ihrem Herrschaftsbereich vereinten\""}, {"kategorie": "", "text": "Diese Ländereien bildeten den Kern der habsburgischen Macht und umfassten weite Teile des heutigen Österreich sowie angrenzende Gebiete. Sie waren das Zentrum der Habsburgerherrschaft im [[Heiligen]] Römischen Reich und später im [[Kaisertum]] Österreich"}, {"kategorie": "", "text": "Bestandteile der österreichischen Erblande: (i) [[Herzogtum]] Österreich (das eigentliche Kernland, zu dem das heutige Niederösterreich und Oberösterreich gehörten. Wien, als Hauptstadt, war das politische und administrative Zentrum der Erblande), (ii) Steiermark, Kärnten und Krain (diese Herzogtümer wurden durch Heiraten und Erbverträge ebenfalls in die habsburgischen Erblande eingegliedert), (iii) Tirol und Vorarlberg (Tirol kam 1363 unter die Kontrolle der [[Habsburger]] und war von großer strategischer Bedeutung, da es die Alpenpässe kontrollierte), (iv) [[Vorderösterreich]] (dazu gehörten verschiedene verstreute Gebiete im heutigen Südwestdeutschland und der Schweiz, die für die habsburgische Kontrolle über den süddeutschen Raum wichtig waren), (v) Salzburg (das Erzstift Salzburg wurde erst im 19. Jahrhundert vollständig in die [[Habsburgermonarchie]] integriert, war aber ein wichtiger Teil der [[Erblande]])"}, {"kategorie": "", "text": "Die österreichischen Erblande bildeten das stabile Herrschaftszentrum der Habsburger und waren das Rückgrat ihrer Macht innerhalb des [[Heiligen]] Römischen Reiches und später des [[Kaisertums]] Österreich. Sie bildeten die Basis für den habsburgischen Einfluss, der sich weit über die Erblande hinaus auf ganz Mitteleuropa erstreckte. Die Habsburger betrachteten diese Gebiete als ihren angestammten Besitz, weshalb sie sie besonders stark verteidigten und pflegten"}, {"kategorie": "", "text": "Die [[Erblande]] wurden zentral von Wien aus regiert, und die habsburgischen [[Kaiser]] und [[Erzherzöge]] konzentrierten ihre Macht zunehmend auf diese Territorien. Die Verwaltung der Erblande war eine wesentliche Aufgabe des [[Wiener]] Hofs und des habsburgischen Beamtenapparats."}]'::jsonb, ''),
  ('heazogtum-oestarreich', 'Heazogtum Östarreich', '', '', '', '', 'Herzogtum Österreich', '[{"kategorie": "hist.", "text": "\"historisches Territorium im [[Heiligen]] Römischen Reich, das den Kern des heutigen Österreichs bildete\""}, {"kategorie": "", "text": "Es wurde 1156 durch die Urkunde \"Privilegium Minus\" zum Herzogtum erhoben und entwickelte sich im Laufe der Jahrhunderte zum Machtzentrum der Habsburger, die Österreich seit dem 13. Jahrhundert regierten. Das Herzogtum spielte eine zentrale Rolle in der politischen Geschichte Mitteleuropas und wurde zur Keimzelle der späteren Habsburgermonarchie"}, {"kategorie": "", "text": "Merkmale des Herzogtums Österreich: (i) Entstehung (das Herzogtum Österreich entstand 1156, als Kaiser [[Friedrich]] I. Barbarossa das [[Privilegium]] Minus erließ, das die [[Markgrafschaft]] Österreich aus dem Herzogtum Bayern herauslöste und sie zum eigenständigen Herzogtum erhob. Das Haus der [[Babenberger]] erhielt die Herrschaft über dieses Gebiet;  (ii) geografische Lage (das Herzogtum umfasste ursprünglich das Gebiet des heutigen Niederösterreich und Oberösterreich. Mit der Ausweitung der habsburgischen Herrschaft wurden weitere Territorien eingegliedert), (iii) die Habsburger (1278 übernahmen die [[Habsburger]] nach der [[Schlacht]] bei Dürnkrut und Jedenspeigen unter [[Rudolf]] I. von Habsburg die Herrschaft über das Herzogtum Österreich. Es blieb von diesem Zeitpunkt an der Kern ihrer Machtbasis und wurde zum Zentrum der habsburgischen [[Erblande]]), (iv) politische Bedeutung (das Herzogtum Österreich war nicht nur ein Territorium, sondern entwickelte sich im Laufe der Jahrhunderte zu einem Machtzentrum innerhalb des [[Heiligen]] Römischen Reiches. Mit Wien als Hauptstadt und Residenz der Habsburger wurde Österreich zunehmend zum Mittelpunkt des politischen Lebens in Mitteleuropa), (v) Aufstieg zum Erzherzogtum (1453 wurde das Herzogtum Österreich unter [[Friedrich]] III., Kaiser des [[Heiligen]] Römischen Reiches, zum [[Erzherzogtum]] erhoben. Dies war eine Aufwertung des Titels, die den besonderen Status Österreichs im Reich verdeutlichte und die Habsburger in ihrer Herrschaft stärkte)"}, {"kategorie": "", "text": "Das Herzogtum war das Kernland der [[Habsburger]], aus dem sie ihre Macht in ganz Mitteleuropa ausdehnten. Es spielte eine Schlüsselrolle bei der Entstehung der habsburgischen Großmacht, die später das [[Kaisertum]] Österreich und die [[österreichisch-ungarische]] Monarchie begründete. Durch seine zentrale Lage und die enge Verbindung mit Wien als Residenzstadt wurde das Herzogtum zu einem bedeutenden politischen, kulturellen und wirtschaftlichen Zentrum Europas."}]'::jsonb, ''),
  ('eazheazogtum-oestarreich', 'Eazheazogtum Östarreich', '', '', '', '', 'Erzherzogtum Österreich', '[{"kategorie": "hist.", "text": "\"historisches Territorium und bedeutender Teil der [[Habsburgermonarchie]], das eine zentrale Rolle in der politischen und territorialen Entwicklung Mitteleuropas spielte\""}, {"kategorie": "", "text": "Das Erzherzogtum Österreich entstand im Jahr 1453, als das zuvor bestehende [[Herzogtum]] Österreich durch Kaiser [[Friedrich]] III. offiziell zum Erzherzogtum erhoben wurde, um den besonderen Status der Habsburger innerhalb des [[Heiligen]] Römischen Reiches zu betonen"}, {"kategorie": "", "text": "Das Erzherzogtum Österreich umfasste ursprünglich das Gebiet des heutigen Niederösterreich und Oberösterreich. Diese Gebiete bildeten den Kern der habsburgischen [[Erblande]] und waren das Zentrum der habsburgischen Macht im Heiligen Römischen Reich"}, {"kategorie": "", "text": "Das Erzherzogtum war der Macht- und Herrschaftsmittelpunkt der Habsburger Dynastie, die nicht nur das Erzherzogtum selbst, sondern auch viele weitere Territorien im Heiligen Römischen Reich und darüber hinaus regierte. Wien, als Hauptstadt des Erzherzogtums, entwickelte sich zum politischen Zentrum des Habsburgerreichs"}, {"kategorie": "", "text": "Die Habsburger Herrscher führten traditionell den Titel [[Erzherzog von Österreich]] und machten das Erzherzogtum zu einem zentralen Teil ihrer Machtpolitik."}]'::jsonb, ''),
  ('adlsgschlecht', 'Ådlsgschlecht', '', '', '', '', 'Adelsgschlecht', '[{"kategorie": "allg.", "text": "\"Familie oder Dynastie, die über mehrere Generationen hinweg dem [[Adel]] angehört und oft politische, militärische oder gesellschaftliche Macht ausübt\""}, {"kategorie": "", "text": "Das bekannteste und mächtigste Adelsgeschlecht in Österreich war das [[Haus]] Habsburg, das über Jahrhunderte hinweg die österreichischen [[Erblande]] regierte und die [[Kaiser]] des [[Heiligen]] Römischen Reiches stellte"}, {"kategorie": "", "text": "Neben den Habsburgern gab es zahlreiche andere Adelsgeschlechter, die als Landesfürsten oder lokale Herrscher wichtige Territorien verwalteten. Beispiele für bedeutende österreichische Adelsfamilien sind die Liechtensteiner, die Schwarzenberger oder die Khevenhüller"}, {"kategorie": "", "text": "Adelsgeschlechter besaßen besondere Privilegien, wie etwa Landbesitz, Steuerfreiheit und politische Einflussmöglichkeiten. Im Gegenzug waren sie oft verpflichtet, dem Kaiser oder Landesfürsten militärischen Dienst zu leisten und Verwaltungsaufgaben zu übernehmen"}, {"kategorie": "", "text": "Der Adel in Österreich spielte bis zum Ende der Monarchie 1918 eine herausragende Rolle in der Politik, Gesellschaft und Kultur. Adelsgeschlechter waren Träger hoher Ämter, Mitglieder des [[Reichsrats]] oder [[Landesstände]] und stellten Generäle, Diplomaten und [[Kirchenfürsten]]."}]'::jsonb, ''),
  ('adl', 'Ådl', '', '', '', '', 'Adel', '[{"kategorie": "hist.", "text": "\"gesellschaftliche Schicht, die über besondere Privilegien, Rechte und gesellschaftliche Stellung verfügte und deren Mitgliedschaft in der Regel erblich war\""}, {"kategorie": "", "text": "Der Adel spielte in der Geschichte Österreichs eine zentrale Rolle, insbesondere während der Zeit der [[Habsburgermonarchie]], wo der Adel politisch, wirtschaftlich und militärisch bedeutenden Einfluss ausübte"}, {"kategorie": "", "text": "Der Adel war in Österreich zumeist erblich und wurde von Generation zu Generation weitergegeben. Adlige trugen Titel wie [[Graf]], [[Freiherr]], [[Fürst]], [[Herzog]] oder [[Erzherzog]], wobei die höheren Titel oft den ranghöchsten [[Adelsgeschlechtern]] vorbehalten waren, wie etwa den [[Habsburgern]]. Auch [[Ritter]] und [[Barone]] zählten zum [[niederen]] Adel"}, {"kategorie": "", "text": "Zu den wichtigsten Adelsfamilien in Österreich gehörte das [[Haus]] Habsburg, das über Jahrhunderte hinweg die Herrschaft über die österreichischen [[Erblande]] und das [[Heilige]] Römische Reich ausübte. Daneben gab es weitere einflussreiche [[Adelsgeschlechter]] wie die Liechtensteiner, Esterházy oder Khevenhüller"}, {"kategorie": "", "text": "Der Adel genoss besondere Vorrechte, darunter Steuerfreiheit, Landbesitz und politische Mitsprache, besonders durch den Einfluss in den [[Landständen]]. Adlige hatten auch die Verpflichtung, dem [[Kaiser]] oder [[Landesfürsten]] militärischen Dienst zu leisten, etwa als Offiziere im Heer, und wurden häufig in hohe Staats- und Verwaltungsämter berufen"}, {"kategorie": "", "text": "Der Adel stellte im Habsburgerreich viele der höchsten Amtsträger, einschließlich Berater des [[Kaisers]], Diplomaten, Militärs und [[Kirchenfürsten]]. Die Adligen hatten durch ihre Teilnahme an den [[Landtagen]] und durch ihre dominierende Rolle in der Verwaltung erheblichen Einfluss auf die Politik der [[Habsburgermonarchie]]"}, {"kategorie": "", "text": "Viele Adelsfamilien förderten Kunst und Kultur. Sie errichteten prächtige Schlösser und Paläste und leisteten einen großen Beitrag zur Entwicklung der [[Barock-]] und [[Rokokoarchitektur]] in Österreich, wie etwa das [[Schloss]] Schönbrunn oder das [[Schloss]] Belvedere in Wien"}, {"kategorie": "", "text": "Mit dem Ende der [[Habsburgermonarchie]] nach dem [[Ersten]] Weltkrieg und der Gründung der [[Republik]] Österreich im Jahr 1918 wurde der Adel formell abgeschafft. Das sogenannte [[Adelsaufhebungsgesetz]] von 1919 verbot adlige Titel, Prädikate und Vorrechte"}, {"kategorie": "", "text": "Der Adel verlor somit seine politische und rechtliche Sonderstellung, doch viele ehemals adlige Familien blieben durch Landbesitz, sozialen Einfluss und familiäre Netzwerke weiterhin gesellschaftlich bedeutend."}]'::jsonb, ''),
  ('adlsaufhebungsgesetz-von-1919', 'Ådlsaufhebungsgesetz von 1919', '', '', '', '', 'Adelsaufhebungsgesetz von 1919', '[{"kategorie": "hist.", "text": "\"ein in der [[Ersten]] Republik Österreich erlassenes Gesetz, das den [[Adel]] als institutionalisierte soziale Schicht in Österreich offiziell abschaffte\""}, {"kategorie": "", "text": "Es trat am 3. April 1919 in Kraft und war Teil der umfassenden Demokratisierungsmaßnahmen, die nach dem Zusammenbruch der [[Habsburgermonarchie]] und dem Ende des [[Ersten]] Weltkriegs durchgeführt wurden"}, {"kategorie": "", "text": "Mit dem Adelsaufhebungsgesetz wurde der Adel als rechtliche Institution abgeschafft. Alle adeligen Vorrechte, Titel und Prädikate (wie „[[Graf]]“, à„Freiherr“, à„Herzog“, à„Fürst“) wurden verboten"}, {"kategorie": "", "text": "Personen, die zuvor dem Adel angehörten, durften ihre adeligen Namensbestandteile nicht mehr führen. Dies betraf unter anderem auch Namenszusätze wie \"von\" oder \"zu\""}, {"kategorie": "", "text": "Das Gesetz betonte die Gleichstellung aller Bürger. Der Adel verlor somit seine rechtlichen und gesellschaftlichen Vorrechte, wie zum Beispiel Steuerbefreiungen oder Privilegien im Militär und in der Verwaltung"}, {"kategorie": "", "text": "Die Verwendung von Adelstiteln oder -prädikaten wurde unter Strafe gestellt. Auch die Annahme von inländischen oder ausländischen Adelstiteln war nicht gestattet."}]'::jsonb, ''),
  ('niidara-adl', 'Niidara Ådl', '', '', '', '', 'Niederer Adel', '[{"kategorie": "allg.", "text": "\"gesellschaftliche Schicht innerhalb des Adels, die im Rang unter dem [[hohen]] Adel (wie [[Fürsten]], [[Herzögen]], [[Grafen]]) stand\""}, {"kategorie": "", "text": "Diese Adelsgruppe umfasste zumeist [[Ritter]], [[Freiherren]] und [[Barone]] sowie andere niedrigere Adelsgrade"}, {"kategorie": "", "text": "Im Gegensatz zum hohen Adel, der oft große Ländereien, politische Macht und enge Verbindungen zum Königshaus hatte, war der niedere Adel oft in regionalen Angelegenheiten tätig und weniger mächtig"}, {"kategorie": "", "text": "Der niedere Adel war oft eng mit dem hohen Adel verbunden und von ihm abhängig. Er diente oft als Verwalter oder militärischer Offizier für mächtigere Adelige und konnte durch den Dienst am Hofe oder auf dem Schlachtfeld aufsteigen"}, {"kategorie": "", "text": "In der [[Habsburgermonarchie]] war der niedere Adel eine wichtige Stütze des Staates, insbesondere in der Verwaltung und im Militär. Auch wenn sie weniger Einfluss hatten als der hohe Adel, spielten sie eine zentrale Rolle im lokalen und regionalen Leben."}]'::jsonb, ''),
  ('hocha-adl', 'Hocha Ådl', '', '', '', '', 'Hoher Adel', '[{"kategorie": "allg.", "text": "\"ranghöchste Schicht innerhalb des [[Adels]], die über erhebliche politische, wirtschaftliche und gesellschaftliche Macht verfügte\""}, {"kategorie": "", "text": "Der hohe Adel umfasste Adelige mit Titeln wie [[Fürst]], [[Herzog]], [[Markgraf]], [[Landgraf]], [[Kurfürst]] und [[Graf]]. Diese Titel standen über denen des [[niederen]] Adels (wie [[Freiherren]] oder [[Rittern]]) und wiesen auf eine hohe Stellung in der gesellschaftlichen Hierarchie hin"}, {"kategorie": "", "text": "Der hohe Adel hatte erheblichen Einfluss auf die Politik. Viele hochrangige Adelige waren nicht nur Besitzer großer Ländereien, sondern hatten auch politische Ämter inne, etwa als Berater des [[Königs]] oder [[Kaisers]], als [[Landesherren]] oder als Mitglieder von [[Reichstagen]] und [[Kurfürstenkollegien]] im [[Heiligen]] Römischen Reich"}, {"kategorie": "", "text": "Hochadelige Familien verfügten oft über riesige Ländereien und damit verbundene Einnahmen. Sie kontrollierten weite landwirtschaftliche Flächen, Burgen, Städte und Handelswege, was ihnen enormen wirtschaftlichen Einfluss verschaffte"}, {"kategorie": "", "text": "Der hohe Adel stand oft in enger Verbindung zu den [[Königshäusern]] oder dem [[Kaiser]] und stellte Mitglieder der königlichen Familien oder [[Hochadeligen]], die in der Nachfolge der Monarchen eine Rolle spielten. Dynastische Heiraten waren ein wichtiges Mittel zur Sicherung und Ausweitung ihrer Macht"}, {"kategorie": "", "text": "In der [[Habsburgermonarchie]] war der hohe Adel eine wichtige Säule des [[Kaisertums]]. Viele einflussreiche Adelsfamilien, wie die Liechtensteiner, Schwarzenberg oder Esterházy, gehörten zum hohen Adel und prägten die Politik und Kultur Österreichs. Der hohe Adel stellte auch die führenden militärischen und politischen Persönlichkeiten des Reiches."}]'::jsonb, ''),
  ('konstitutionelle-monarchii', 'Konstitutionelle Monarchii', '', '', '', '', 'Konstitutionelle Monarchie', '[{"kategorie": "hist.", "text": "\"Regierungsform, in der die Macht des [[Monarchen]] durch eine Verfassung (Konstitution) begrenzt wird\""}, {"kategorie": "", "text": "Im Gegensatz zur absoluten Monarchie, in der der [[Monarch]] uneingeschränkte Herrschaft ausübt, teilt der Monarch in einer konstitutionellen Monarchie seine Macht mit anderen Institutionen, in der Regel einem Parlament oder einer gesetzgebenden Versammlung. Diese Form der Regierung kombiniert Elemente einer Monarchie mit demokratischen Prinzipien"}, {"kategorie": "", "text": "Vor den [[Revolutionen]] von 1848 war Österreich eine absolutistische Monarchie, in der der Kaiser nahezu uneingeschränkte Macht besaß. Die [[Habsburger-Dynastie]] regierte über ein multikulturelles und multiethnisches Reich mit zahlreichen Territorien und Völkern, und politische Mitbestimmung durch das Volk war weitgehend ausgeschlossen"}, {"kategorie": "", "text": "Kaiser [[Ferdinand]] I. wurde durch den Druck der revolutionären Bewegungen gezwungen, Reformen zu akzeptieren und 1848 eine erste Verfassung zu erlassen. Obwohl der Kaiser formal eine starke Position beibehielt, insbesondere in militärischen und außenpolitischen Angelegenheiten, wurde seine Macht in der Innenpolitik zunehmend durch den [[Reichsrat]] und das [[Kabinett]] eingeschränkt. Der Kaiser ernannte den [[Ministerpräsidenten]], aber dieser musste in der Regel die Unterstützung des Parlaments haben, was den Einfluss des Kaisers auf die Tagespolitik reduzierte"}, {"kategorie": "", "text": "Die konstitutionelle Monarchie in Österreich endete nach dem [[Ersten]] Weltkrieg und dem Zusammenbruch der [[Doppelmonarchie]]. Die militärischen Niederlagen und die nationalen Unabhängigkeitsbewegungen in den verschiedenen Teilen des Reiches führten 1918 zum Sturz des [[Kaiserreichs]]."}]'::jsonb, ''),
  ('koarl-von-auaspeag', 'Koarl von Auaspeag', '', '', '', '', 'Karl von Auersperg', '[{"kategorie": "", "text": "Er war ein Verfechter des Liberalismus und setzte sich für eine [[konstitutionelle]] Monarchie mit einer starken Rolle des Parlaments ein"}, {"kategorie": "", "text": "Karl von Auersperg entstammte einer alten und einflussreichen Adelsfamilie und begann seine politische Karriere als Mitglied des [[Herrenhauses]], der oberen Kammer des österreichischen [[Reichsrates]], in dem er sich rasch als entschiedener Verfechter liberaler und verfassungsmäßiger Prinzipien profilierte"}, {"kategorie": "", "text": "Auersperg wurde [[Ministerpräsident]] von [[Cisleithanien]], der österreichischen Reichshälfte der [[Doppelmonarchie]], und übte dieses Amt von 1867 bis 1868 aus. Auersperg galt als führender Kopf der liberalen Partei (Verfassungspartei) und setzte sich für eine starke [[konstitutionelle]] Monarchie ein, bei der das Parlament eine zentrale Rolle spielen sollte. Seine Regierung versuchte, die Macht des Kaisers in der Gesetzgebung und Verwaltung zu beschränken und das Parlament als entscheidende Institution im politischen System zu etablieren"}, {"kategorie": "", "text": "Aufgrund politischer Differenzen mit Kaiser Franz Joseph I. und der wachsenden Spannungen zwischen den verschiedenen Nationalitäten innerhalb des Habsburgerreiches trat Auersperg 1868 nach nur einem Jahr im Amt als Ministerpräsident zurück. Dennoch blieb er eine wichtige politische Figur und spielte weiterhin eine prominente Rolle im [[Herrenhaus]] des österreichischen Reichsrates, wo er sich weiterhin für liberale Werte und die Aufrechterhaltung der konstitutionellen Monarchie einsetzte."}]'::jsonb, ''),
  ('eduard-taaffe', 'Eduard Taaffe', '', '', '', '', 'Eduard Taaffe', '[{"kategorie": "", "text": "Er war vor allem bekannt für seine Rolle als [[Ministerpräsident]] der österreichischen Reichshälfte ([[Cisleithanien]]) der [[Doppelmonarchie]] Österreich-Ungarn"}, {"kategorie": "", "text": "Taaffe amtierte zweimal als Ministerpräsident (1868–1870 und 1879–1893) und prägte die österreichische Innenpolitik durch seine pragmatische und konservative Herangehensweise an die sozialen und nationalen Spannungen im Habsburgerreich"}, {"kategorie": "", "text": "Eduard Taaffe stammte aus einer alten irischen Adelsfamilie, die sich in Österreich niedergelassen hatte. Er war ein enger Jugendfreund von Kaiser [[Franz]] Joseph I., was ihm den Zugang zu hohen politischen Ämtern erleichterte"}, {"kategorie": "", "text": "In seiner ersten Amtszeit als Ministerpräsident versuchte Taaffe, die innenpolitischen Spannungen im Habsburgerreich zu bewältigen, die sich aus den Konflikten zwischen den verschiedenen Nationalitäten ergaben. Seine Amtszeit war jedoch kurz, da er auf die wachsenden Konflikte zwischen den liberalen Kräften und den nationalistischen Bewegungen, insbesondere der Tschechen, nicht langfristig reagieren konnte"}, {"kategorie": "", "text": "Nach einem längeren politischen Rückzug kehrte Taaffe 1879 als Ministerpräsident zurück. Diese Amtszeit war die längste und prägendste Phase seiner politischen Karriere"}, {"kategorie": "", "text": "Taaffe war bekannt für seine Politik des \"konservativen Ausgleichs\" zwischen den konservativen Kräften, dem aufstrebenden Bürgertum und den verschiedenen nationalen Gruppen"}, {"kategorie": "", "text": "Obwohl er ein Konservativer war, erkannte Taaffe die Notwendigkeit sozialer Reformen, um Unruhen zu verhindern und das Reich zu stabilisieren. Eine der bedeutendsten politischen Maßnahmen Taaffes war die [[Wahlrechtsreform]] von 1882, durch die das Wahlrecht schrittweise auf größere Teile der Bevölkerung ausgedehnt wurde. Dies war ein wichtiger Schritt in Richtung einer breiteren politischen Partizipation"}, {"kategorie": "", "text": "In den frühen 1890er Jahren geriet Taaffes Regierung zunehmend unter Druck, insbesondere durch die wachsenden Spannungen zwischen den nationalen Gruppen und die Forderungen nach weitergehenden Reformen. Schließlich wurde er 1893 zum Rücktritt gezwungen, nachdem er einen Vorschlag zur umfassenderen Erweiterung des Wahlrechts nicht durchsetzen konnte"}, {"kategorie": "", "text": "Nach seinem Rücktritt zog sich Taaffe aus der Politik zurück und starb zwei Jahre später, im Jahr 1895."}]'::jsonb, ''),
  ('woirechtsrefoam-von-1882', 'Woirechtsrefoam von 1882', '', '', '', '', 'Wahlrechtsreform von 1882', '[{"kategorie": "hist.", "text": "\"bedeutende Reform, die das Wahlrecht für die Mitglieder des österreichischen [[Reichsrates]] (das Parlament der [[cisleithanischen]] Reichshälfte der [[Doppelmonarchie]] Österreich-Ungarn) auf eine breitere Bevölkerungsschicht ausdehnte\""}, {"kategorie": "", "text": "Die Reform fand unter der Regierung von [[Eduard]] Taaffe statt und führte zu einer schrittweisen Ausweitung der politischen Partizipation, blieb jedoch weiterhin auf einem beschränkten Zensuswahlrecht basierend"}, {"kategorie": "", "text": "Die Reform senkte die Einkommensgrenzen, die bisher erforderlich waren, um wahlberechtigt zu sein. Dies führte dazu, dass mehr Bürger das Recht erhielten, Abgeordnete in den [[Reichsrat]] zu wählen, insbesondere aus der Mittelschicht und unter den städtischen Arbeitern"}, {"kategorie": "", "text": "Trotz der Erweiterung des Wahlrechts blieb es weiterhin auf einem [[Zensuswahlrecht]] basierend, was bedeutete, dass das Wahlrecht an ein gewisses Einkommen oder Steuerleistung gebunden war. Diese Reform führte also nicht zu einem allgemeinen Wahlrecht, sondern zu einer relativ begrenzten Öffnung des politischen Systems für neue Wählergruppen"}, {"kategorie": "", "text": "[[Eduard]] Taaffe nutzte die Wahlrechtsreform von 1882 als Teil seiner Strategie des \"konservativen Ausgleichs\", um soziale Spannungen abzubauen und gleichzeitig die Herrschaft der Habsburger Monarchie zu stabilisieren. Durch die Erweiterung des Wahlrechts hoffte er, eine breitere Basis für die [[Monarchie]] zu schaffen, indem er politisch moderaten Kräften mehr Mitsprache gewährte"}, {"kategorie": "", "text": "Die Reform ebnete den Weg für die späteren Wahlrechtsreformen, insbesondere die umfassendere [[Wahlrechtsreform]] von 1907, die schließlich das allgemeine männliche Wahlrecht in [[Cisleithanien]] einführte."}]'::jsonb, ''),
  ('woirechtsrefoam-von-1907', 'Woirechtsrefoam von 1907', '', '', '', '', 'Wahlrechtsreform von 1907', '[{"kategorie": "hist.", "text": "\"historisch bedeutender Schritt hin zur Demokratisierung des politischen Systems in der österreichischen Reichshälfte ([[Cisleithanien]]) der [[Doppelmonarchie]] Österreich-Ungarn\""}, {"kategorie": "", "text": "Diese Reform führte erstmals das allgemeine männliche Wahlrecht für die Wahlen zum Abgeordnetenhaus des österreichischen [[Reichsrates]] ein und beendete das bis dahin gültige [[Zensuswahlrecht]], bei dem nur wohlhabende Bürger wahlberechtigt waren"}, {"kategorie": "", "text": "Mit der Reform von 1907 wurde das Wahlrecht erheblich ausgeweitet: Alle männlichen Bürger des cisleithanischen Teils der Doppelmonarchie, die das 24. Lebensjahr vollendet hatten, durften nun wählen, unabhängig von Einkommen oder Steuerleistung"}, {"kategorie": "", "text": "Vor der Reform war das Wahlrecht nach einem [[Kurienwahlsystem]] organisiert, bei dem die Bevölkerung nach verschiedenen sozialen und wirtschaftlichen Gruppen (Kurien) eingeteilt wurde, etwa Großgrundbesitzer, Handelskammern oder Städte, die jeweils eine bestimmte Anzahl an Abgeordneten wählen durften. Diese Kurien waren stark verzerrt zugunsten der wohlhabenderen Schichten"}, {"kategorie": "", "text": "Mit der Wahlrechtsreform von 1907 wurde dieses Kurienwahlsystem abgeschafft, was eine gleichmäßigere und gerechtere Verteilung der politischen Macht ermöglichte. Jeder wahlberechtigte Mann hatte nun eine Stimme, und alle Wähler wurden gleich behandelt."}]'::jsonb, ''),
  ('konstituiirende-nationalvasaummlung', 'Konstituiirende Nationalvasaummlung', '', '', '', '', 'Konstituierende Nationalversammlung', '[{"kategorie": "hist.", "text": "\"Parlament, das nach der Gründung eines neuen Staates oder nach tiefgreifenden politischen Umbrüchen einberufen wird, um eine Verfassung zu entwerfen und zu verabschieden sowie den politischen Rahmen des neuen Staates festzulegen\""}, {"kategorie": "", "text": "In Österreich bezieht sich der Begriff insbesondere auf die Versammlung, die nach dem Ende der [[Habsburgermonarchie]] 1918 einberufen wurde, um die politische und verfassungsrechtliche Grundlage der [[Ersten]] Republik Österreich zu schaffen"}, {"kategorie": "", "text": "Nach dem Zusammenbruch der [[Monarchie]] wurde am 12. November 1918 die [[Republik]] Deutschösterreich ausgerufen, die sich als Nachfolgestaat des [[Habsburgerreiches]] verstand. Um eine demokratische und rechtliche Grundlage für den neuen Staat zu schaffen, wurde eine Konstituierende Nationalversammlung gewählt. Sie sollte die erste demokratische Verfassung Österreichs ausarbeiten und die neue Republik institutionell verankern"}, {"kategorie": "", "text": "Die Wahlen zur Konstituierenden Nationalversammlung fanden am 16. Februar 1919 statt. Dies war eine historische Wahl, denn es war die erste Wahl in Österreich, bei der das allgemeine und gleiche Wahlrecht für Männer und Frauen galt. Frauen konnten somit zum ersten Mal in der Geschichte des Landes an einer nationalen Wahl teilnehmen"}, {"kategorie": "", "text": "Die Wahlen verliefen nach dem Prinzip des Verhältniswahlrechts, was bedeutete, dass die verschiedenen politischen Parteien entsprechend ihrer Wählerstimmen Sitze im Parlament erhielten"}, {"kategorie": "", "text": "Die [[Sozialdemokratische]] Arbeiterpartei (SDAP) und die [[Christlichsoziale]] Partei (CSP) waren die stärksten politischen Kräfte in der Konstituierenden Nationalversammlung. Auch die [[Großdeutsche]] Volkspartei war vertreten"}, {"kategorie": "", "text": "Nach intensiven Beratungen verabschiedete die Konstituierende Nationalversammlung im Oktober 1920 die [[Bundesverfassung]] der [[Ersten]] Republik Österreich. Diese Verfassung legte die Grundlagen für eine [[parlamentarische]] Demokratie, in der die Regierung vom Vertrauen des Parlaments abhängig war, und sah einen föderalistischen Staatsaufbau vor, der den Bundesländern weitgehende Autonomie einräumte"}, {"kategorie": "", "text": "Die Verfassung von 1920 wurde unter Federführung des Rechtsgelehrten Hans [[Kelsen]] entworfen und ist bis heute, mit einigen Änderungen, die Grundlage der politischen Ordnung in Österreich."}]'::jsonb, ''),
  ('kooperativa-foederalismus', 'Kooperativa Föderalismus', '', '', '', '', 'Kooperativer Föderalismus', '[{"kategorie": "pol.", "text": "\"politisches Konzept in Österreich, bei dem [[Bund]] und Länder in einem föderalen Staat eng zusammenarbeiten, um politische Aufgaben und Herausforderungen gemeinsam zu bewältigen\""}, {"kategorie": "", "text": "Im Gegensatz zum kompetitiven Föderalismus, bei dem die verschiedenen Ebenen klar voneinander getrennt agieren und oft in Konkurrenz zueinander stehen, zeichnet sich der kooperative Föderalismus durch eine starke Zusammenarbeit und Abstimmung zwischen den Regierungsebenen aus"}, {"kategorie": "", "text": "Die Verteilung der Mittel erfolgt durch den [[Finanzausgleich]], der gemeinsam zwischen Bund und Ländern ausgehandelt wird. Dieser Mechanismus sorgt dafür, dass Länder mit geringeren Steuereinnahmen dennoch genügend finanzielle Ressourcen zur Verfügung haben"}, {"kategorie": "", "text": "Der kooperative Föderalismus ermöglicht eine enge Abstimmung zwischen den verschiedenen Regierungsebenen und kann dazu beitragen, effektive und einheitliche Lösungen für nationale Herausforderungen zu finden. Gleichzeitig bietet er den Ländern die Möglichkeit, Einfluss auf die nationale Gesetzgebung zu nehmen, wodurch regionale Interessen berücksichtigt werden können."}]'::jsonb, ''),
  ('absolute-monarchii', 'Absolute Monarchii', '', '', '', '', 'Absolute Monarchie', '[{"kategorie": "hist.", "text": "\"historische Regierungsform in Österreich, in welcher der [[Monarch]] uneingeschränkte Macht über den Staat und seine Institutionen ausübte, ohne durch eine Verfassung oder ein Parlament kontrolliert zu werden\""}, {"kategorie": "", "text": "In dieser Form der Herrschaft waren alle politischen Entscheidungen, einschließlich der [[Gesetzgebung]], [[Verwaltung]] und [[Justiz]], direkt dem Willen des Monarchen unterworfen. Dies bedeutete, dass der [[Kaiser]] die höchste und letztlich alleinige Autorität darstellte, und seine Entscheidungen nicht durch demokratische oder repräsentative Einrichtungen eingeschränkt wurden"}, {"kategorie": "", "text": "Ein prägendes Beispiel der absoluten Monarchie in Österreich ist die Herrschaft unter [[Maria]] Theresia und [[Joseph]] II. im 18. Jahrhundert. Maria Theresia und ihr Sohn Joseph II. führten weitreichende Reformen durch, die auf dem Gedanken der Aufklärung basierten, um die Effizienz und Zentralisierung des Staates zu erhöhen"}, {"kategorie": "", "text": "Zu dieser Zeit bestand die zentrale Idee darin, dass der Monarch als „Vater des Volkes“ agierte und das Wohl des Staates über alle anderen Interessen stellte. Joseph II., etwa, förderte eine umfassende Staatsreform, die Bereiche wie Bildung, Justiz und Wirtschaft erfasste, um die Verwaltung zu vereinheitlichen und die Macht des Kaisers zu stärken"}, {"kategorie": "", "text": "Im Verlauf des 19. Jahrhunderts änderte sich diese Regierungsform durch die Einflüsse der liberalen und nationalistischen Bewegungen, was schließlich zur Einführung der [[konstitutionellen]] Monarchie und zur Einschränkung der Macht des Kaisers führte."}]'::jsonb, ''),
  ('obasta-gerichtshof', 'Obasta Gerichtshof', '', '', '', '', 'Oberster Gerichtshof', '[{"kategorie": "allg.", "text": "\"höchstes Gericht der ordentlichen Gerichtsbarkeit in Österreich\""}, {"kategorie": "", "text": "Der Oberste Gerichtshof ist die letzte Instanz für [[Zivil-]] und [[Strafsachen]] und entscheidet somit endgültig über Rechtsstreitigkeiten, die von den ordentlichen Gerichten bearbeitet werden"}, {"kategorie": "", "text": "Der OGH hat seinen Sitz in Wien und spielt eine zentrale Rolle bei der Wahrung und Weiterentwicklung der [[Rechtsprechung]] in Österreich"}, {"kategorie": "", "text": "Aufgaben und Zuständigkeiten des Obersten Gerichtshofs:  (i) Letzte Instanz für Zivil- und Strafsachen: Der OGH entscheidet in letzter Instanz über [[Rechtsmittel]] ([[Revisionen]] und [[Nichtigkeitsbeschwerden]]) in Zivil- und Strafverfahren. Seine Urteile sind endgültig und können nicht weiter angefochten werden;  (ii) Rechtsfortbildung und Präzedenzfälle: Da der OGH in letzter Instanz urteilt, prägt er die Rechtsprechung in Österreich maßgeblich. Die von ihm entwickelten Leitentscheidungen haben großen Einfluss auf die Auslegung und Anwendung des österreichischen Rechts durch alle anderen Gerichte;  (iii) Einheitliche Rechtsauslegung: Der OGH sorgt durch seine Entscheidungen dafür, dass [[Gesetze]] einheitlich angewandt werden, und trägt zur Konsistenz und Kohärenz der Rechtsprechung im gesamten Land bei;  (iv) Beratung in Gesetzgebungsfragen: In besonderen Fällen kann der OGH den [[Gesetzgeber]] durch Gutachten oder Empfehlungen bei der Weiterentwicklung des Rechts beraten;  (v) Beurteilung von Grundsatzfragen: Der OGH behandelt oft komplexe Rechtsfragen von grundsätzlicher Bedeutung, die Auswirkungen auf die [[Gesellschaft]] haben und die Rechtsentwicklung beeinflussen"}, {"kategorie": "", "text": "Der Oberste Gerichtshof ist neben dem [[Verwaltungsgerichtshof]] (VwGH) und dem [[Verfassungsgerichtshof]] (VfGH) eines der drei Höchstgerichte in Österreich. Während der OGH die ordentliche Gerichtsbarkeit abdeckt, ist der VwGH für die Verwaltungsgerichtsbarkeit zuständig, und der VfGH prüft die Verfassungsmäßigkeit von Gesetzen und den Schutz der Grundrechte"}, {"kategorie": "", "text": "Der OGH ist in verschiedene Senate aufgeteilt, die sich auf Zivil- oder Strafrecht spezialisieren. Jeder Senat besteht aus mehreren Richtern, und Entscheidungen werden meist in einem Kollegium gefällt. Der Präsident des Obersten Gerichtshofs führt die Verwaltung des Gerichts und repräsentiert es nach außen."}]'::jsonb, ''),
  ('ex-officio', 'Ex Officio', '', '', '', '', 'Ex Officio', '[{"kategorie": "jur.", "text": "\"lateinischer Begriff, der „von Amts wegen“ bedeutet\""}, {"kategorie": "", "text": "In rechtlichem Kontext bezeichnet er Handlungen oder Entscheidungen, die eine [[Behörde]], ein [[Gericht]] oder eine andere offizielle Stelle eigenständig und unabhängig von einem Antrag oder einer Initiative von außen ergreift"}, {"kategorie": "", "text": "Wenn etwas ex officio geschieht, wird die Handlung also automatisch und verpflichtend durch die zuständige Stelle ausgeführt, sobald bestimmte Voraussetzungen erfüllt sind"}, {"kategorie": "", "text": "Beispiele für die Anwendung des Prinzips „ex officio“:  (i) Strafverfolgung: Bei einem [[Offizialdelikt]] ergreifen die [[Strafverfolgungsbehörden]] von sich aus Maßnahmen, sobald sie von der Tat Kenntnis erhalten, unabhängig davon, ob ein Opfer oder eine andere Person einen [[Strafantrag]] gestellt hat;  (ii) Verfahrensleitung und Beweiserhebung: In bestimmten Verfahren, wie etwa im [[Verwaltungs-]] oder [[Strafrecht]], können Gerichte oder Behörden von Amts wegen Beweise erheben oder den Sachverhalt umfassend aufklären, ohne dass eine Partei dies beantragen muss;  (iii) Bestellung von [[Sachverständigen]] oder Vertretern: Gerichte können in einigen Fällen von Amts wegen einen Sachverständigen oder Verfahrensvertreter bestellen, wenn dies für die Klärung eines Sachverhalts oder den Schutz der Beteiligten erforderlich ist"}, {"kategorie": "", "text": "Der Grundsatz „ex officio“ stellt sicher, dass in bestimmten Angelegenheiten die [[öffentliche]] Ordnung und das Interesse der Gesellschaft gewahrt bleiben, indem zuständige Stellen unabhängig und eigenverantwortlich tätig werden können."}]'::jsonb, ''),
  ('oeffentliche-oadnung', 'Öffentliche Oadnung', '', '', '', '', 'Öffentliche Ordnung', '[{"kategorie": "jur.", "text": "\"Zustand des gesellschaftlichen Friedens, der Sicherheit und des geordneten Zusammenlebens in einer Gemeinschaft\""}, {"kategorie": "", "text": "In rechtlichem Sinne umfasst die öffentliche Ordnung alle Regelungen, Vorschriften und Normen, die das Verhalten der Mitglieder einer [[Gesellschaft]] so steuern, dass das allgemeine Wohl, die Sicherheit und die Rechte aller geschützt sind"}, {"kategorie": "", "text": "Wesentliche Merkmale der öffentlichen Ordnung:  (i) Sicherung der öffentlichen Sicherheit: Die öffentliche Ordnung beinhaltet Maßnahmen, die Gefahren für das Leben, die Gesundheit und das Eigentum der Bürger abwehren und so für Sicherheit im öffentlichen Raum sorgen;  (ii) Wahrung des gesellschaftlichen Friedens: Ein zentrales Ziel der öffentlichen Ordnung ist es, Konflikte zu vermeiden und das friedliche Zusammenleben zu sichern, etwa durch [[Gesetze]], die das Verhalten in der Öffentlichkeit regulieren;  (iii) Einhaltung von sozialen und rechtlichen Normen: Zur öffentlichen Ordnung gehören gesetzliche Vorschriften, aber auch soziale und ethische Normen, die als allgemeiner Konsens in der Gesellschaft bestehen, wie beispielsweise das Verbot von Gewalt oder Respekt vor Eigentum;  (iv) Schutz der allgemeinen [[Rechtsgüter]]: Dazu zählen unter anderem der Schutz der Umwelt, der Schutz von Eigentum, aber auch der Schutz von öffentlichen Einrichtungen und allgemein zugänglichen Gütern;  (v) Durchsetzung durch staatliche Organe: Die Gewährleistung der öffentlichen Ordnung obliegt staatlichen Institutionen wie der [[Polizei]], [[Gerichten]] und [[Verwaltungsbehörden]], die befugt sind, Verstöße zu ahnden und Ordnung herzustellen"}, {"kategorie": "", "text": "Beispiele für den Schutz der öffentlichen Ordnung:  (i) Vorschriften zur Vermeidung von Lärmbelästigung,  (ii) Verbote von Randalieren oder Vandalismus in der Öffentlichkeit,  (iii) Gesetze zur Regelung des Verkehrs oder der Nutzung von öffentlichen Räumen,  (iv) Maßnahmen gegen Störungen des gesellschaftlichen Friedens, etwa durch Gewalt oder Hassreden"}, {"kategorie": "", "text": "Die öffentliche Ordnung ist ein zentraler Pfeiler des [[Rechtsstaats]] und sorgt dafür, dass das Leben in einer Gemeinschaft reibungslos und im Einklang mit geltenden Gesetzen und gesellschaftlichen Werten abläuft."}]'::jsonb, ''),
  ('oeffentliches-recht', 'Öffentliches Recht', '', '', '', '', 'Öffentliches Recht', '[{"kategorie": "jur.", "text": "\"jener Bereich des Rechts, der die Rechtsbeziehungen zwischen dem [[Staat]] und seinen [[Bürgern]] sowie die Organisation und Funktionsweise staatlicher Institutionen regelt\""}, {"kategorie": "", "text": "Das Öffentliche Recht umfasst alle [[Rechtsnormen]], die das Verhalten des Staates und seiner Organe steuern und ihr Verhältnis zu den Einzelpersonen und anderen öffentlichen Körperschaften bestimmen"}, {"kategorie": "", "text": "Anders als das [[Zivilrecht]], das Beziehungen zwischen Privatpersonen betrifft, ist das öffentliche Recht durch ein Über- und Unterordnungsverhältnis gekennzeichnet: Der Staat tritt gegenüber dem Bürger als hoheitliche Instanz auf"}, {"kategorie": "", "text": "Wesentliche Bereiche des Öffentlichen Rechts:  (i) Verfassungsrecht: Das [[Verfassungsrecht]] bildet die Grundlage des öffentlichen Rechts und regelt die Organisation des Staates, die Verteilung der [[Staatsgewalt]] und die [[Grundrechte]] der Bürger. Es enthält etwa die Vorschriften zur [[Gewaltenteilung]], zu den Kompetenzen von [[Parlament]], [[Regierung]] und [[Gerichten]] sowie zu den Grundrechten;  (ii) Verwaltungsrecht: Das [[Verwaltungsrecht]] umfasst die Regelungen zur Tätigkeit der staatlichen Verwaltung. Dazu gehören z. B. das Polizei- und Ordnungsrecht, das Baurecht, das Sozialrecht und das Umweltrecht;  (iii) [[Strafrecht]]: Obwohl es teils eng mit dem [[Zivilrecht]] verbunden ist, ist das Strafrecht ein Bereich des öffentlichen Rechts, da der [[Staat]] die [[Strafverfolgung]] und Bestrafung von Verstößen gegen seine Gesetze durchsetzt;  (iv) [[Völkerrecht]] und [[Europarecht]]: Das Völkerrecht regelt die Beziehungen zwischen Staaten und internationalen Organisationen, während das Europarecht die Rechtsbeziehungen innerhalb der Europäischen Union betrifft"}, {"kategorie": "", "text": "Grundprinzipien des Öffentlichen Rechts: (i) Über- und Unterordnungsverhältnis: Im öffentlichen Recht tritt der Staat als übergeordnete Instanz auf, während der Bürger im untergeordneten Verhältnis steht. Dies äußert sich etwa in der Möglichkeit des Staates, durch Verwaltungsakte Verpflichtungen oder Verbote gegenüber Bürgern anzuordnen;  (ii) [[Legalitätsprinzip]]: Staatliche Organe und Behörden dürfen nur auf der Grundlage gesetzlicher Regelungen handeln („Kein Handeln ohne Gesetz“). Dies stellt sicher, dass alle Eingriffe in die Rechte der Bürger nur auf rechtlicher Grundlage erfolgen;  (iii) Verhältnismäßigkeitsprinzip: Maßnahmen des Staates müssen geeignet, erforderlich und angemessen sein, um die Grundrechte des Einzelnen nicht unverhältnismäßig einzuschränken"}, {"kategorie": "", "text": "Das Öffentliche Recht sorgt dafür, dass die Organisation des Staates funktioniert und die Rechtsordnung durchgesetzt wird. Es schützt die [[Grundrechte]] und Freiheiten der [[Bürger]], indem es den staatlichen Eingriffen enge Grenzen setzt"}, {"kategorie": "", "text": "Gewährleistung der [[Rechtsstaatlichkeit]]: Das Öffentliche Recht schafft rechtliche Kontrolle und Transparenz für das staatliche Handeln, sodass Bürger Rechtsschutz gegen rechtswidrige Maßnahmen in Anspruch nehmen können."}]'::jsonb, ''),
  ('aussaoadentliche-revision', 'Aussaoadentliche Revision', '', '', '', '', 'Außerordentliche Revision', '[{"kategorie": "jur.", "text": "\"Rechtsmittel im Verwaltungs- und Zivilrecht, das es ermöglicht, eine gerichtliche Entscheidung durch das Höchstgericht – im Verwaltungsbereich den [[Verwaltungsgerichtshof]] (VwGH) und im Zivilrecht den [[Obersten]] Gerichtshof (OGH) – überprüfen zu lassen\""}, {"kategorie": "", "text": "Die Außerordentliche Revision kommt nur dann zum Einsatz, wenn die ordentliche Revision nicht zulässig ist, also wenn das Gericht der unteren Instanz festgestellt hat, dass die Entscheidung keine grundsätzliche Rechtsfrage von allgemeiner Bedeutung enthält"}, {"kategorie": "", "text": "Die außerordentliche Revision ist ein sogenanntes außergewöhnliches Rechtsmittel, da sie nur unter bestimmten Bedingungen zulässig ist:  (i) Vorliegen einer grundsätzlichen Rechtsfrage: Der Revisionswerber (die Person, die die Revision einlegt) muss darlegen, dass eine grundsätzliche Rechtsfrage besteht, deren Klärung im Interesse der Rechtssicherheit, der Rechtseinheit oder der Rechtsentwicklung liegt;  (ii) Keine ordentliche Revision möglich: Eine außerordentliche Revision kann nur eingebracht werden, wenn das Gericht der unteren Instanz die ordentliche Revision ausgeschlossen hat;  (iii) Zulassung durch das Höchstgericht: Der Verwaltungsgerichtshof oder Oberste Gerichtshof entscheidet, ob die außerordentliche Revision angenommen wird, und überprüft die angeführte Rechtsfrage auf ihre grundsätzliche Bedeutung"}, {"kategorie": "", "text": "Der Prozess der außerordentlichen Revision läuft folgendermaßen ab:  (i) Einbringung des Antrags: Der Antrag auf außerordentliche Revision muss innerhalb der vorgeschriebenen Frist (meist vier Wochen nach Zustellung der Entscheidung) schriftlich eingereicht werden;  (ii) Vorprüfung durch das Höchstgericht: Das Höchstgericht (VwGH oder OGH) prüft zunächst, ob die Revision tatsächlich eine grundsätzliche Rechtsfrage aufwirft und ob sie zugelassen wird;  (iii) Entscheidung in der Hauptsache: Wenn die außerordentliche Revision zugelassen wird, überprüft das Höchstgericht die Entscheidung der vorherigen Instanz und entscheidet über die aufgeworfenen Rechtsfragen"}, {"kategorie": "", "text": "Die außerordentliche Revision ist ein wichtiger Mechanismus zur Wahrung der Rechtseinheit und -sicherheit in Österreich. Sie stellt sicher, dass auch in Fällen, in denen keine ordentliche Revision zulässig ist, Rechtsfragen von grundsätzlicher Bedeutung geklärt und höchstrichterlich überprüft werden können. Dies verhindert Rechtsunsicherheiten und sorgt dafür, dass die [[Rechtsprechung]] im Einklang mit übergeordneten Prinzipien des Rechts und der Gerechtigkeit bleibt"}, {"kategorie": "", "text": "Kurz gesagt, ermöglicht die außerordentliche Revision eine letzte Instanzprüfung durch das Höchstgericht, allerdings nur unter strengen Voraussetzungen und wenn grundsätzliche Rechtsfragen betroffen sind."}]'::jsonb, ''),
  ('oadentliches-gericht', 'Oadentliches Gericht', '', '', '', '', 'Ordentliches Gericht', '[{"kategorie": "allg.", "text": "\"Gericht, das zur ordentlichen Gerichtsbarkeit gehört\""}, {"kategorie": "", "text": "Dies umfasst jene Gerichte, die mit allgemeinen zivilrechtlichen und strafrechtlichen Angelegenheiten betraut sind. Sie sind Teil des allgemeinen Justizsystems und zuständig für die Anwendung des [[Allgemeinen]] Bürgerlichen Gesetzbuches (ABGB), des [[Strafgesetzbuches]] (StGB) sowie anderer allgemeiner Rechtsvorschriften"}, {"kategorie": "", "text": "In Österreich zählen zu den ordentlichen Gerichten insbesondere:  (i) Bezirksgerichte,  (ii) Landesgerichte,  (iii) Oberlandesgerichte,  (iv) Oberster Gerichtshof"}, {"kategorie": "", "text": "Neben der ordentlichen Gerichtsbarkeit gibt es auch andere spezialisierte Gerichtsbarkeiten, wie etwa die Verwaltungsgerichtsbarkeit, die Arbeits- und Sozialgerichtsbarkeit, sowie die Finanzgerichtsbarkeit. Diese sind für spezifische Rechtsbereiche (z.B. öffentliches Recht, Arbeitsrecht, Sozialrecht, Steuerrecht) zuständig und werden nicht als \"ordentliche\" Gerichte bezeichnet"}, {"kategorie": "", "text": "Die ordentlichen Gerichte sind sowohl für Zivilrechtsstreitigkeiten als auch für Strafsachen zuständig"}, {"kategorie": "", "text": "Sie folgen in Österreich einem [[Instanzenzug]]: Zunächst verhandeln Bezirksgsgerichte bzw. Landesgerichte als erste Instanz, und es bestehen in höherer Instanz die Oberlandesgerichte und schließlich der Oberste Gerichtshoff als Höchstgericht der ordentlichen Gerichtsbarkeit"}, {"kategorie": "", "text": "Ein ordentliches Gericht ist somit ein Gericht, das allgemeine Rechtsfragen im Bereich des [[Zivil-]] und Strafrechts entscheidet und einen zentralen Bestandteil des Justizsystems bildet."}]'::jsonb, ''),
  ('recht-auf-gehoea', 'Recht auf Gehöa', '', '', '', '', 'Recht auf Gehör', '[{"kategorie": "jur.", "text": "\"grundlegendes Verfahrensrecht im österreichischen Rechtssystem und ein zentrales Element des fairen Verfahrens\""}, {"kategorie": "", "text": "Das Recht auf Gehör sichert Personen, die von einem behördlichen oder gerichtlichen Verfahren betroffen sind, die Möglichkeit, ihre Argumente, Beweise und Stellungnahmen in das Verfahren einzubringen und zu den entscheidungserheblichen Tatsachen Stellung zu nehmen, bevor eine endgültige Entscheidung getroffen wird"}, {"kategorie": "", "text": "Das Recht auf Gehör wird durch mehrere Bestimmungen gestützt:  (i) Verfassungsrechtliche Verankerung: Es ergibt sich aus dem [[Rechtsstaatsprinzip]] der österreichischen [[Bundesverfassung]] und ist als solches ein Grundpfeiler des rechtlichen Gehörs und des fairen Verfahrens;  (ii) Verfahrensrechtliche Regelungen: Das [[Allgemeine]] Verwaltungsverfahrensgesetz (AVG) und die [[Zivilprozessordnung]] (ZPO) enthalten spezifische Bestimmungen, die sicherstellen, dass Betroffene angehört werden;  (iii) [[Europäische]] Menschenrechtskonvention (EMRK): Artikel 6 der EMRK garantiert das Recht auf ein faires Verfahren und somit das Recht auf Gehör auch im österreichischen Recht"}, {"kategorie": "", "text": "Das Recht auf Gehör umfasst folgende wesentliche Elemente: (i) Information über das Verfahren und Sachverhalte: Betroffene müssen über das Verfahren und die wesentlichen Fakten und Beweise, die für die Entscheidung relevant sind, informiert werden;  (ii) Möglichkeit zur Stellungnahme: Die betroffene Person hat das Recht, zu den ihr gegenüber erhobenen Vorwürfen oder behördlichen Sachverhalten Stellung zu nehmen und Beweise vorzulegen, die ihre Position stützen;  (iii) Einsicht in Akten: In den meisten Fällen umfasst das Recht auf Gehör auch das Recht auf Akteneinsicht, sodass die betroffene Person alle entscheidungsrelevanten Dokumente einsehen kann;  (iv) Berücksichtigung der Stellungnahme: Die Behörde oder das Gericht ist verpflichtet, die Stellungnahme der betroffenen Person ernsthaft zu berücksichtigen und darf sie nicht unbeachtet lassen;  (v) Anwendung und Durchsetzung des Rechts auf Gehör: Das Recht auf Gehör ist in nahezu allen behördlichen und gerichtlichen Verfahren anwendbar, darunter [[Verwaltungsverfahren]] (vor dem Erlass eines [[Bescheides]] muss die betroffene Person in der Regel angehört werden, insbesondere wenn die Entscheidung sie negativ betrifft), [[Gerichtsverfahren]] (in zivil- und strafrechtlichen Verfahren hat der Angeklagte oder die beklagte Partei das Recht, vor einer Entscheidung angehört zu werden), [[Disziplinarverfahren]] und [[Verwaltungsstrafverfahren]] (auch in diesen Verfahren ist das Recht auf Gehör von zentraler Bedeutung)"}, {"kategorie": "", "text": "Wird das Recht auf Gehör verletzt, kann dies zur Aufhebung der Entscheidung oder zur Rückverweisung des Verfahrens führen, da eine solche Entscheidung als rechtswidrig angesehen wird. Die betroffene Person kann dann beispielsweise [[Beschwerde]] bei den zuständigen Gerichten, etwa dem [[Verwaltungsgerichtshof]] oder dem [[Verfassungsgerichtshof]], einlegen."}]'::jsonb, ''),
  ('oigemeines-vawoitungsvafoarensgesetz', 'Oigemeines Vawoitungsvafoarensgesetz', '', '', '', '', 'Allgemeines Verwaltungsverfahrensgesetz', '[{"kategorie": "", "text": "Es legt die Verfahrensvorschriften fest, die Behörden bei der Entscheidung von Verwaltungsangelegenheiten beachten müssen, und stellt sicher, dass das Verwaltungshandeln im Einklang mit den Grundsätzen des [[Rechtsstaats]] erfolgt\""}, {"kategorie": "", "text": "Das AVG findet in allen Verwaltungsverfahren Anwendung, die nicht durch spezielle Verfahrensgesetze geregelt sind. Dazu gehören Verfahren in Bereichen wie:  (i) Gewerberecht, (ii) Baurecht, (iii) Sozialversicherungsrecht, (iv) Umweltrecht, (v) Verwaltungsstrafrecht"}, {"kategorie": "", "text": "In speziellen Verwaltungsbereichen gibt es jedoch auch Sonderverfahrensgesetze, die das AVG ergänzen oder in einzelnen Aspekten ersetzen können"}, {"kategorie": "", "text": "Das AVG umfasst eine Vielzahl von Vorschriften, die den Ablauf und die Gestaltung von Verwaltungsverfahren prägen. Zu den wichtigsten Regelungen zählen:  (i) Parteirechte und [[Recht]] auf Gehör: Das AVG legt fest, dass alle Verfahrensparteien über ihre Rechte und Pflichten informiert werden und das Recht haben, in einem Verfahren angehört zu werden;  (ii) \nAkteneinsicht: Den Parteien wird das Recht auf Akteneinsicht gewährt, um die Transparenz zu fördern und die eigene Verteidigung im Verfahren zu ermöglichen"}, {"kategorie": "", "text": "Das AVG beschreibt den Ablauf eines Verwaltungsverfahrens von der Antragstellung bis zur Entscheidung und regelt dabei die wesentlichen Schritte, einschließlich:  (i) Einbringung von Anträgen und Beschwerden;  (ii) Ermittlung des Sachverhalts durch die Behörde,\nDurchführung von Anhörungen und Beweiserhebungen;  (iii) Erlass von [[Bescheiden]]"}, {"kategorie": "", "text": "Das AVG legt fest, dass Entscheidungen in Form eines Bescheids erlassen werden müssen, der eine nachvollziehbare Begründung enthält und die Entscheidung der Behörde schriftlich dokumentiert"}, {"kategorie": "", "text": "[[Rechtsmittel]] und [[Beschwerde]]: Das Gesetz regelt die Möglichkeiten zur Beschwerde und zum [[Rechtsschutz]], wie die Einbringung von Berufungen und Beschwerden bei den [[Verwaltungsgerichten]]"}, {"kategorie": "", "text": "Fristen und Säumnisbeschwerde: Das AVG enthält Fristregelungen für die Bearbeitung von Anträgen und Bescheiden. Bei Verzögerungen seitens der Behörde können Bürger eine [[Säumnisbeschwerde]] einreichen."}]'::jsonb, ''),
  ('europaeischa-gerichtshof-fia-menschenrechte', 'Europäischa Gerichtshof fia Menschenrechte', '', '', '', '', 'Europäischer Gerichtshof für Menschenrechte', '[{"kategorie": "", "text": "Der EGMR ist für Bürger der Mitgliedstaaten die höchste Instanz, um Verletzungen der in der EMRK garantierten Rechte zu prüfen und gegebenenfalls zu ahnden"}, {"kategorie": "", "text": "Der EGMR schützt die in der EMRK festgelegten Menschenrechte und Grundfreiheiten, darunter das Recht auf Leben, das Verbot der Folter, das Recht auf ein faires Verfahren, die Meinungs- und Religionsfreiheit sowie den Schutz des Eigentums"}, {"kategorie": "", "text": "Die Aufgaben und Zuständigkeiten des Gerichts umfassen: (i) Entscheidung über Beschwerden: Der EGMR prüft Beschwerden von Individuen, Gruppen oder Staaten gegen Mitgliedstaaten des Europarates, die eine Verletzung der in der EMRK festgelegten Rechte geltend machen;  (ii) Kontrolle der Umsetzung der EMRK: Der EGMR interpretiert die Konvention und entwickelt sie weiter, indem er im Kontext aktueller Entwicklungen Urteile fällt und so zur Weiterentwicklung des europäischen Menschenrechtsschutzes beiträgt;  (iii) Erteilung von Rechtsentscheidungen: Der EGMR kann im Rahmen seiner Urteile verbindliche Entscheidungen fällen, die den beklagten Staat verpflichten, Maßnahmen zu ergreifen, um die Menschenrechtsverletzung zu beheben"}, {"kategorie": "", "text": "Damit eine Beschwerde vor dem EGMR verhandelt werden kann, müssen bestimmte Voraussetzungen erfüllt sein: (i) Ausschöpfung des nationalen Rechtswegs: Bevor eine Beschwerde an den EGMR gerichtet werden kann, müssen alle innerstaatlichen [[Rechtsmittel]] ausgeschöpft worden sein. Der EGMR ist also eine letzte Instanz nach den nationalen Gerichten;  (ii) Antragsfrist: Die Beschwerde muss innerhalb einer Frist von sechs Monaten nach der endgültigen Entscheidung des nationalen Gerichts eingereicht werden;  (iii) \nZulässigkeitsvoraussetzungen: Die Beschwerde muss eine konkrete Verletzung eines in der EMRK verankerten Rechts betreffen und darf nicht offensichtlich unbegründet sein"}, {"kategorie": "", "text": "Der Europäische Gerichtshof für Menschenrechte besteht aus Richtern aus jedem Mitgliedstaat des Europarates, wobei jeder Richter unabhängig handelt und nicht den Interessen seines Heimatlandes verpflichtet ist. Die Richter werden für eine Amtszeit von neun Jahren gewählt"}, {"kategorie": "", "text": "Der EGMR ist in verschiedene Kammern und eine Große Kammer unterteilt:  (i) Einzelrichter und Ausschüsse: Prüfen Beschwerden auf offensichtliche Unzulässigkeit;  (ii) Kammern: Verhandeln die meisten Fälle und bestehen aus sieben Richtern;  (iii) Große Kammer: Diese Kammer aus 17 Richtern befasst sich mit besonders wichtigen oder komplexen Fällen, die Grundsatzentscheidungen erfordern"}, {"kategorie": "", "text": "Die Urteile des EGMR sind rechtsverbindlich für die betroffenen Staaten. Nach einem Urteil ist der betroffene Staat verpflichtet, die Menschenrechtsverletzung zu beheben und Maßnahmen zu ergreifen, um ähnliche Verstöße in Zukunft zu vermeiden. Die Umsetzung und Einhaltung der Urteile wird durch das Ministerkomitee des Europarates überwacht, das sicherstellt, dass die Urteile in die nationale Gesetzgebung und Praxis umgesetzt werden."}]'::jsonb, ''),
  ('oeffentliches-intaresse', 'Öffentliches Intaresse', '', '', '', '', 'Öffentliches Interesse', '[{"kategorie": "jur.", "text": "\"Interesse, das die Gesamtheit der [[Gesellschaft]] oder wesentliche Teile davon betrifft und das Wohl der Allgemeinheit fördert\""}, {"kategorie": "", "text": "Es ist ein Grundsatz im [[Verwaltungs-]] und Verfassungsrecht, der zur Rechtfertigung staatlicher Eingriffe und Maßnahmen herangezogen wird, wenn individuelle Rechte eingeschränkt werden sollen. Dabei steht das öffentliche Interesse im Spannungsverhältnis zum individuellen Interesse und bildet eine zentrale Grundlage für die Abwägung zwischen dem Wohl der Allgemeinheit und den Rechten des Einzelnen"}, {"kategorie": "", "text": "Das öffentliche Interesse ist in verschiedenen Bereichen relevant und bildet häufig die Grundlage für staatliche Eingriffe oder Regelungen:  (i) Sicherheit und Ordnung: Maßnahmen zum Schutz der öffentlichen Sicherheit und Ordnung, z. B. im Polizeirecht oder im Baurecht, werden durch das öffentliche Interesse gerechtfertigt;  (ii) Gesundheit und Umweltschutz: Vorschriften im Gesundheitswesen, Umweltauflagen und Schutzmaßnahmen für die natürliche Umwelt dienen dem öffentlichen Interesse an Gesundheit und Nachhaltigkeit;  (iii) Infrastruktur: Der Bau und Erhalt öffentlicher Infrastruktur wie Straßen, Schulen und Krankenhäuser liegt im öffentlichen Interesse, um eine funktionierende Gesellschaft und Wirtschaft zu gewährleisten;  (iv) Soziale Gerechtigkeit und Wohlfahrt: Sozialpolitische Maßnahmen, wie die Förderung von leistbarem Wohnraum oder der Schutz von Arbeitnehmerrechten, dienen ebenfalls dem öffentlichen Interesse"}, {"kategorie": "", "text": "Das öffentliche Interesse steht häufig in einem Spannungsverhältnis zu individuellen Freiheitsrechten und Eigentumsrechten. Bei staatlichen Eingriffen, die auf das öffentliche Interesse gestützt werden, ist daher stets eine Verhältnismäßigkeitsprüfung erforderlich. Diese umfasst:  (i) Geeignetheit: Die Maßnahme muss geeignet sein, das öffentliche Interesse zu fördern;  (ii) Erforderlichkeit: Es dürfen keine milderen Mittel existieren, die das Ziel ebenfalls erreichen könnten, ohne individuelle Rechte in gleichem Maß einzuschränken;  (iii) Angemessenheit: Das öffentliche Interesse muss so stark wiegen, dass es die Beeinträchtigung individueller Rechte rechtfertigt"}, {"kategorie": "", "text": "Diese Abwägung wird insbesondere durch Gerichte wie den [[Verfassungsgerichtshof]] oder den [[Verwaltungsgerichtshof]] kontrolliert, die prüfen, ob die jeweiligen Eingriffe mit dem Prinzip des [[Rechtsstaats]] vereinbar sind."}]'::jsonb, ''),
  ('unvaletzlichkeit-des-hausrechts', 'Unvaletzlichkeit des Hausrechts', '', '', '', '', 'Unverletzlichkeit des Hausrechts', '[{"kategorie": "jur.", "text": "\"Grundrecht in Österreich, das in Artikel 9 des [[Staatsgrundgesetzes]] über die allgemeinen Rechte der Staatsbürger (StGG) verankert ist\""}, {"kategorie": "", "text": "Dieses Grundrecht schützt die Privatsphäre und den Wohnraum der Bürger und gewährleistet, dass die eigenen vier Wände vor unbefugtem Eindringen und staatlichen Eingriffen bewahrt bleiben"}, {"kategorie": "", "text": "Die Unverletzlichkeit des Hausrechts ist eine wesentliche Ausprägung des Rechts auf Privatsphäre und zählt zu den Grundrechten, die die individuelle Freiheit und Selbstbestimmung der Bürger sichern"}, {"kategorie": "", "text": "Die Unverletzlichkeit des Hausrechts bedeutet, dass staatliche Behörden, wie die Polizei oder andere Organe der Exekutive, Wohnräume und Geschäftsräume nicht ohne gesetzliche Grundlage betreten oder durchsuchen dürfen"}, {"kategorie": "", "text": "Dieses Grundrecht umfasst:  (i) Schutz vor unbefugtem Eindringen: Niemand darf ohne Einwilligung des Bewohners in dessen Wohnung oder Privaträume eindringen;  (ii) Schutz vor Durchsuchungen: Durchsuchungen von Wohnungen und Geschäftsräumen sind nur unter bestimmten rechtlichen Voraussetzungen zulässig, etwa bei einem richterlichen Durchsuchungsbefehl;  (iii) Schutz der Privatsphäre: Das Hausrecht dient dem Schutz der Privatsphäre und stellt sicher, dass die eigene Wohnung ein geschützter Raum bleibt, in dem die Bürger frei von staatlicher Kontrolle leben können"}, {"kategorie": "", "text": "Wie andere Grundrechte kann auch die Unverletzlichkeit des Hausrechts unter bestimmten Bedingungen eingeschränkt werden. Diese Einschränkungen sind jedoch eng definiert und nur unter strengen Voraussetzungen möglich, um Missbrauch zu verhindern. Beispiele für Ausnahmen sind: (i) [[Durchsuchungsbefehl]]: Eine Wohnung oder ein Privatraum darf nur dann gegen den Willen des Bewohners betreten werden, wenn ein richterlicher Durchsuchungsbefehl vorliegt. Dieser wird nur erteilt, wenn ein dringender Verdacht auf eine Straftat oder eine andere rechtliche Grundlage gegeben ist;  (ii) [[Gefahr]] im Verzug: In dringenden Fällen, wenn etwa eine unmittelbare Gefahr für Leib und Leben besteht, kann die Polizei auch ohne Durchsuchungsbefehl eingreifen, um die Gefahr abzuwenden. Dies nennt man „Gefahr im Verzug“;  (iii) [[Exekutionstitel]] bei Zwangsvollstreckung: Bei gerichtlichen Zwangsvollstreckungen, beispielsweise zur Eintreibung von Schulden, darf der Exekutor unter bestimmten Voraussetzungen die Wohnung betreten, jedoch nur mit einem entsprechenden Vollstreckungstitel."}]'::jsonb, ''),
  ('gleichheit-voam-gesetz', 'Gleichheit voam Gesetz', '', '', '', '', 'Gleichheit vor dem Gesetz', '[{"kategorie": "jur.", "text": "\"fundamentales Rechtsprinzip, das bedeutet, dass alle Menschen in gleicher Weise vor dem Gesetz behandelt werden müssen, unabhängig von persönlichen Merkmalen wie Geschlecht, Herkunft, Religion, sozialem Status oder politischer Überzeugung\""}, {"kategorie": "", "text": "In Österreich ist die Gleichheit vor dem Gesetz als [[Grundrecht]] in der [[Bundesverfassung]] verankert, insbesondere in Artikel 7 der [[österreichischen]] Bundesverfassung (B-VG) und in der [[Europäischen]] Menschenrechtskonvention (EMRK)"}, {"kategorie": "", "text": "Wesentliche Merkmale der Gleichheit vor dem Gesetz sind:  (i) \nKeine willkürliche Ungleichbehandlung: Der Staat darf keine unterschiedlichen Rechtsfolgen festlegen, die auf willkürlichen oder unsachlichen Unterscheidungen basieren. Eine Ungleichbehandlung ist nur dann zulässig, wenn sie durch einen sachlichen Grund gerechtfertigt ist und dem Gemeinwohl dient;  (ii) Schutz vor Diskriminierung: Gleichheit vor dem Gesetz bedeutet, dass niemand aufgrund persönlicher Merkmale wie Geschlecht, Alter, Rasse, Religion, politischer Meinung oder sozialer Herkunft benachteiligt oder bevorzugt werden darf;  (iii) [[Verhältnismäßigkeitsprinzip]]: Wenn der Gesetzgeber Unterschiede zwischen Personen oder Gruppen macht, muss dies verhältnismäßig sein und einen legitimen Zweck verfolgen. Eingriffe in die Gleichbehandlung müssen angemessen und erforderlich sein;  (iv) Gleichheit bei der Rechtsanwendung: Gleichheit vor dem Gesetz verpflichtet nicht nur die [[Gesetzgebung]], sondern auch die [[Verwaltung]] und die [[Gerichte]]. Die [[Rechtsprechung]] muss also sicherstellen, dass gleiche Fälle gleich behandelt werden und dass vergleichbare Situationen vergleichbar entschieden werden"}, {"kategorie": "", "text": "Die Gleichheit vor dem Gesetz ist eine zentrale Säule der [[Rechtsstaatlichkeit]] und der [[Demokratie]]. Sie sichert die Gerechtigkeit und Verlässlichkeit des Rechtssystems und schützt die [[Bürger]] vor Diskriminierung und willkürlichen staatlichen Eingriffen. Das Prinzip sorgt dafür, dass Gesetze und staatliche Maßnahmen nicht zu Ungleichbehandlung führen, es sei denn, diese ist klar begründet und notwendig."}]'::jsonb, ''),
  ('recht-auf-peasoenliche-freiheit', 'Recht auf peasönliche Freiheit', '', '', '', '', 'Recht auf persönliche Freiheit', '[{"kategorie": "jur.", "text": "\"Grundrecht in Österreich, das den Schutz der individuellen Bewegungsfreiheit und Selbstbestimmung garantiert\""}, {"kategorie": "", "text": "Es sichert den Bürgern das Recht, sich frei zu bewegen, Entscheidungen eigenständig zu treffen und vor willkürlichen oder ungerechtfertigten staatlichen Eingriffen in ihre persönliche Freiheit geschützt zu sein"}, {"kategorie": "", "text": "Dieses Recht ist in Artikel 8 des [[Staatsgrundgesetzes]] über die allgemeinen Rechte der Staatsbürger (StGG) sowie in der [[Europäischen]] Menschenrechtskonvention (EMRK) verankert"}, {"kategorie": "", "text": "Das Recht auf persönliche Freiheit beinhaltet mehrere grundlegende Aspekte:  (i) Schutz vor willkürlicher Festnahme und Inhaftierung: Niemand darf ohne gesetzliche Grundlage festgenommen, eingesperrt oder in sonstiger Weise in seiner Freiheit eingeschränkt werden. Jede Freiheitsentziehung muss durch ein Gesetz gerechtfertigt sein und unterliegt strengen Bedingungen;  (ii) Recht auf freie Bewegung: Jeder Mensch hat das Recht, sich innerhalb des Landes frei zu bewegen, seinen Wohnsitz zu wählen und Entscheidungen über seine Lebensweise eigenständig zu treffen, solange er dabei nicht die Rechte anderer verletzt;  (iii) Recht auf Verteidigung: Personen, die festgenommen oder inhaftiert wurden, haben das Recht, die Gründe der Freiheitsentziehung zu erfahren, sich verteidigen zu können und Zugang zu rechtlichem Beistand zu haben. Dies dient dem Schutz vor staatlicher Willkür und der Wahrung der individuellen Rechte;  (iv) Recht auf gerichtliche Überprüfung: Menschen, deren Freiheit eingeschränkt wurde, haben das Recht, die Rechtmäßigkeit der Freiheitsentziehung durch ein unabhängiges Gericht überprüfen zu lassen. Dies stellt sicher, dass die Freiheitsentziehung rechtmäßig und verhältnismäßig ist"}, {"kategorie": "", "text": "Das Recht auf persönliche Freiheit ist zwar umfassend, jedoch nicht uneingeschränkt. Unter bestimmten Umständen kann es eingeschränkt werden, sofern die Einschränkungen verhältnismäßig und gesetzlich vorgesehen sind. Beispiele für zulässige Einschränkungen sind: (i) Strafrechtliche Maßnahmen: Bei Verdacht auf eine Straftat dürfen Personen festgenommen oder in Untersuchungshaft genommen werden, solange dies gesetzlich begründet und verhältnismäßig ist;  (ii) Sicherheitsmaßnahmen: Zur Abwehr unmittelbarer Gefahren für die öffentliche Sicherheit oder Ordnung kann eine vorübergehende Freiheitsbeschränkung, wie etwa bei einer polizeilichen Festnahme, erfolgen;  (iii) Maßnahmen im Gesundheitsbereich: Bei schweren psychischen Erkrankungen oder bei Infektionsgefahr kann es zur Unterbringung in psychiatrischen Einrichtungen oder zur Quarantäne kommen, wenn dies im Interesse der Betroffenen selbst oder der Gesellschaft notwendig ist"}, {"kategorie": "", "text": "Bürger, deren Recht auf persönliche Freiheit verletzt wurde oder die sich zu Unrecht in Haft befinden, können gerichtlichen [[Rechtsschutz]] in Anspruch nehmen. Der [[Verfassungsgerichtshof]] und der [[Oberste]] Gerichtshof überprüfen, ob eine Freiheitsentziehung oder Einschränkung der Bewegungsfreiheit im Einklang mit den [[Grundrechten]] steht. Auch der [[Europäische]] Gerichtshof für Menschenrechte (EGMR) kann angerufen werden, wenn eine Verletzung der persönlichen Freiheit im Sinne der [[EMRK]] vorliegt."}]'::jsonb, ''),
  ('freiheit-der-person', 'Freiheit der Person', '', '', '', '', 'Freiheit der Person', '[{"kategorie": "jur.", "text": "\"Grundrecht in Österreich, welches das Recht auf persönliche Freiheit und Selbstbestimmung schützt\""}, {"kategorie": "", "text": "Dieses Grundrecht sichert jedem Einzelnen das Recht, sich frei zu bewegen und nicht ohne rechtmäßige Grundlage festgenommen oder inhaftiert zu werden. Es ist in mehreren Rechtsquellen verankert, insbesondere in Artikel 8 des [[Staatsgrundgesetzes]] über die allgemeinen Rechte der Staatsbürger (StGG) und in der [[Europäischen]] Menschenrechtskonvention (EMRK)"}, {"kategorie": "", "text": "\"Freiheit der Person\" bedeutet:  (i) Schutz vor willkürlicher Festnahme und Inhaftierung: Niemand darf willkürlich oder ohne gesetzliche Grundlage festgenommen oder inhaftiert werden. Jede Freiheitsentziehung muss gesetzlich gerechtfertigt sein und unterliegt strengen formellen und materiellen Voraussetzungen;  (ii) Recht auf Freiheit und Sicherheit: Jeder Mensch hat das Recht, sich frei zu bewegen und sein Leben ohne ungerechtfertigte Eingriffe des Staates zu gestalten. Freiheitsbeschränkungen sind nur zulässig, wenn sie gesetzlich vorgesehen sind und einem legitimen Zweck dienen;  (iii) Unabhängige Überprüfung von Freiheitsentziehungen: Personen, die festgenommen oder inhaftiert wurden, haben das Recht, die Rechtmäßigkeit ihrer Freiheitsentziehung von einem Gericht überprüfen zu lassen. Dies stellt sicher, dass eine Haft oder Festnahme den gesetzlichen Anforderungen entspricht;  (iv) Recht auf Information und Verteidigung: Im Falle einer Festnahme oder Inhaftierung muss die betroffene Person über die Gründe der Freiheitsentziehung informiert werden und hat das Recht auf Verteidigung, einschließlich des Rechts, einen Anwalt zu konsultieren"}, {"kategorie": "", "text": "Die Freiheit der Person ist ein wichtiges Grundrecht, kann aber unter bestimmten Voraussetzungen eingeschränkt werden. Diese Einschränkungen müssen gesetzlich geregelt sein und den Grundsatz der Verhältnismäßigkeit wahren. Beispiele für zulässige Freiheitsbeschränkungen sind:  (i) Strafrechtliche Haft: Bei begründetem Verdacht einer [[Straftat]] darf eine Person festgenommen und bis zum Abschluss des Gerichtsverfahrens in Untersuchungshaft genommen werden, sofern dies notwendig und verhältnismäßig ist;  (ii) Sicherheitshaft und Verwaltungshaft: In bestimmten Situationen, etwa zur Gefahrenabwehr oder aus Gründen der öffentlichen Sicherheit, kann eine Person vorübergehend festgenommen werden, etwa bei akuten Bedrohungen oder zur Sicherung der öffentlichen Ordnung;  (iii) Maßnahmen gegen psychische Erkrankung: Personen mit schweren psychischen Erkrankungen, die eine Gefahr für sich selbst oder andere darstellen, können unter strengen Auflagen in psychiatrische Einrichtungen eingewiesen werden;  (iv) Quarantäne und Seuchenschutz: Zur Eindämmung von Infektionskrankheiten kann die Bewegungsfreiheit eingeschränkt werden, beispielsweise durch Quarantänemaßnahmen im Rahmen des Seuchenschutzes"}, {"kategorie": "", "text": "Personen, deren Freiheit eingeschränkt wurde, haben das Recht, sich an ein Gericht zu wenden und die Rechtmäßigkeit ihrer Festnahme oder Inhaftierung überprüfen zu lassen. In Österreich ist der [[Verfassungsgerichtshof]] eine zentrale Instanz, die prüft, ob Freiheitsbeschränkungen mit den verfassungsmäßigen Rechten vereinbar sind. Betroffene können auch [[Beschwerden]] an den [[Europäischen]] Gerichtshof für Menschenrechte (EGMR) richten, wenn sie der Ansicht sind, dass ihre Freiheit der Person verletzt wurde."}]'::jsonb, ''),
  ('oestarreichische-vafossungsoadnung', 'Östarreichische Vafossungsoadnung', '', '', '', '', 'Österreichische Verfassungsordnung', '[{"kategorie": "jur.", "text": "\"alle Rechtsnormen und Grundsätze, welche die staatliche Ordnung, Organisation und [[Grundrechte]] in Österreich regeln\""}, {"kategorie": "", "text": "Die Verfassungsordnung stellt das oberste rechtliche Fundament des Staates dar und definiert die Struktur des politischen Systems, die Rechte und Pflichten der Staatsorgane sowie die Grundrechte der Bürger"}, {"kategorie": "", "text": "Die Verfassungsordnung wird durch mehrere Verfassungsdokumente und -bestimmungen gebildet und umfasst die Grundprinzipien der Verfassung, die als unveränderbar gelten, darunter das [[Demokratieprinzip]], das [[Rechtsstaatsprinzip]], das [[Bundesstaatsprinzip]] und das [[Republikprinzip]]"}, {"kategorie": "", "text": "Elemente der österreichischen Verfassungsordnung: (i) [[Bundes-Verfassungsgesetz]] (B-VG): Das Bundes-Verfassungsgesetz ist das zentrale Verfassungsgesetz Österreichs und regelt die Grundstrukturen des Staates, einschließlich der [[Gewaltenteilung]], der Aufgaben der Staatsorgane, der Gesetzgebungsverfahren und der Verteilung der Kompetenzen zwischen [[Bund]] und [[Ländern]];  (ii) [[Staatsgrundgesetz]] von 1867: Das Staatsgrundgesetz über die allgemeinen Rechte der Staatsbürger enthält wesentliche Grundrechte, wie die [[Gleichheit]] vor dem Gesetz, die [[persönliche]] Freiheit, die [[Eigentumsfreiheit]] und die [[Religionsfreiheit]], die noch immer einen zentralen Bestandteil der Verfassungsordnung bilden;  (iii) [[Europäische]] Menschenrechtskonvention (EMRK): Die Europäische Menschenrechtskonvention, die seit 1964 Verfassungsrang hat, erweitert die Grundrechte der Bürger und ergänzt das Staatsgrundgesetz durch Rechte wie das Recht auf Leben, das Verbot der Folter und das Recht auf ein faires Verfahren;  (iv) Weitere Verfassungsgesetze und -bestimmungen: Die Verfassungsordnung umfasst zusätzlich spezifische Verfassungsgesetze und -bestimmungen, etwa das Finanz-Verfassungsgesetz, das [[Neutralitätsgesetz]] oder das Bundesgesetz über die rechtliche Stellung der Kirchen und Religionsgesellschaften. Diese Gesetze haben Verfassungsrang und ergänzen das B-VG"}, {"kategorie": "", "text": "Die Verfassungsordnung genießt besonderen Schutz. Änderungen an Verfassungsgesetzen und insbesondere an den Grundprinzipien der Verfassung sind nur unter sehr strengen Bedingungen möglich: (i) Zweidrittelmehrheit im [[Nationalrat]]: Verfassungsänderungen erfordern eine qualifizierte Mehrheit von zwei Dritteln im Nationalrat;  (ii) [[Volksabstimmung]] bei Grundprinzipien: Wenn die Grundprinzipien der Verfassung, wie das [[Demokratie-]] oder [[Bundesstaatsprinzip]], verändert werden sollen, muss eine verbindliche Volksabstimmung durchgeführt werden"}, {"kategorie": "", "text": "Die Verfassungsordnung ist das höchste rechtliche Fundament und ein Schutzmechanismus für [[Demokratie]], [[Rechtsstaatlichkeit]] und [[Grundrechte]] in Österreich. Sie sichert die Rechte der Bürger, definiert die Strukturen der Staatsorganisation und gewährleistet eine verlässliche und gerechte Staatsführung. Sie schützt vor willkürlicher Macht und stellt sicher, dass das Handeln des Staates stets den Grundwerten des Gemeinwesens entspricht."}]'::jsonb, ''),
  ('kinda-und-jugendaunwoidschoft', 'Kinda- und Jugendaunwoidschoft', '', '', '', '', 'Kinder- und Jugendanwaltschaft', '[{"kategorie": "", "text": "Die KJA dient als Anlaufstelle für Kinder, Jugendliche, Eltern, Erziehungsberechtigte und Fachkräfte, die Unterstützung oder Beratung in Fragen des Kinder- und Jugendschutzes benötigen"}, {"kategorie": "", "text": "Die Kinder- und Jugendanwaltschaften sind auf Landesebene organisiert, das heißt, jedes österreichische Bundesland hat eine eigene Kinder- und Jugendanwaltschaft"}, {"kategorie": "", "text": "Kinder und Jugendliche können sich direkt an die KJA wenden, wenn sie sich ungerecht behandelt fühlen oder Probleme im Zusammenhang mit Behörden, Schulen oder Betreuungseinrichtungen haben. Die KJA prüft Beschwerden und vermittelt zwischen den Betroffenen und den verantwortlichen Institutionen"}, {"kategorie": "", "text": "Fachliche Stellungnahmen und Empfehlungen: Die Kinder- und Jugendanwaltschaft erstellt Berichte und Empfehlungen zu kinderrechtlichen Themen und gibt fachliche Stellungnahmen ab, etwa in Gesetzgebungsverfahren oder bei der Verbesserung von Betreuungseinrichtungen und Bildungsinstitutionen"}, {"kategorie": "", "text": "Die KJA arbeitet eng mit Schulen, sozialen Einrichtungen, Jugendämtern und anderen Institutionen zusammen, um den Schutz und das Wohl von Kindern und Jugendlichen sicherzustellen. Dabei ist die KJA häufig in der Rolle eines Vermittlers und Beraters tätig"}, {"kategorie": "", "text": "Die Kinder- und Jugendanwaltschaften sind in den jeweiligen Jugendhilfegesetzen der [[Bundesländer]] verankert, was ihnen rechtliche Grundlage und Zuständigkeit verleiht. Jedes Bundesland hat eine eigene Kinder- und Jugendanwaltschaft, die autonom und unabhängig von anderen staatlichen Behörden arbeitet. Die KJA ist keine Behörde im klassischen Sinne, sondern eine unabhängige [[Ombudseinrichtung]]"}, {"kategorie": "", "text": "Die Kinder- und Jugendanwaltschaft ist ein wesentlicher Teil des Kinder- und Jugendschutzes in Österreich und bietet jungen Menschen eine niederschwellige Anlaufstelle für ihre Anliegen und Probleme. Sie stärkt die Kinderrechte und trägt dazu bei, dass Kinder und Jugendliche eine Stimme in der Gesellschaft haben und ihre Rechte geschützt werden. Durch Beratung, Öffentlichkeitsarbeit und politische Arbeit wirkt die KJA aktiv daran mit, die Lebensbedingungen und den Schutz junger Menschen zu verbessern."}]'::jsonb, ''),
  ('recht-auf-leben', 'Recht auf Leben', '', '', '', '', 'Recht auf Leben', '[{"kategorie": "jur.", "text": "\"fundamentales Menschenrecht, das den Schutz des Lebens jedes einzelnen Menschen garantiert\""}, {"kategorie": "", "text": "Es verpflichtet den Staat und seine Organe, das Leben seiner Bürger zu schützen und Maßnahmen zu ergreifen, um es gegen ungerechtfertigte Eingriffe zu bewahren"}, {"kategorie": "", "text": "Das Recht auf Leben ist in Artikel 2 der [[Europäischen]] Menschenrechtskonvention (EMRK) verankert und hat in Österreich Verfassungsrang. Es bildet die Grundlage für andere [[Menschenrechte]], da es das grundlegendste Recht des Einzelnen ist"}, {"kategorie": "", "text": "Das Recht auf Leben verbietet es dem Staat, Menschen willkürlich oder ohne rechtliche Grundlage das Leben zu nehmen. Der Staat und seine Organe dürfen keine Maßnahmen ergreifen, die das Leben eines Menschen grundlos gefährden oder beenden"}, {"kategorie": "", "text": "In Österreich und den meisten europäischen Staaten ist die Todesstrafe abgeschafft. Der Artikel 2 der [[EMRK]] enthält Ausnahmeregelungen, die jedoch durch das Protokoll Nr. 6 und Nr. 13 zur EMRK für alle Mitgliedstaaten des Europarates abgeschafft wurden. Österreich hat diese Protokolle ratifiziert, sodass die Todesstrafe vollständig verboten ist"}, {"kategorie": "", "text": "Der Staat hat eine positive Verpflichtung, das Leben seiner Bürger aktiv zu schützen. Dies umfasst Maßnahmen zur Bekämpfung von Lebensgefahren, wie beispielsweise den Schutz vor Gewaltverbrechen, Notdienste und Maßnahmen zum Schutz der öffentlichen Gesundheit"}, {"kategorie": "", "text": "Der Staat hat eine gewisse Verantwortung, eine funktionierende und zugängliche Gesundheitsversorgung bereitzustellen, um das Leben der Bürger zu schützen und zu erhalten"}, {"kategorie": "", "text": "Ermittlungen bei Todesfällen: Bei verdächtigen Todesfällen, insbesondere bei Todesfällen im Gewahrsam des Staates oder bei Polizeieinsätzen, muss der Staat eine umfassende und unabhängige Untersuchung durchführen, um eine mögliche Verantwortlichkeit aufzuklären"}, {"kategorie": "", "text": "Der Europäische Gerichtshof für Menschenrechte (EGMR) spielt eine zentrale Rolle bei der Durchsetzung des Rechts auf Leben in Europa. Der EGMR prüft, ob der Staat seine Schutzpflichten erfüllt und ob es zu einer Verletzung des Rechts auf Leben gekommen ist. Bürger können den EGMR anrufen, wenn sie der Meinung sind, dass ihr Recht auf Leben verletzt wurde und sie keine nationale Lösung gefunden haben."}]'::jsonb, ''),
  ('oestarreichischa-geweakschoftsbund', 'Östarreichischa Geweakschoftsbund', '', '', '', '', 'Österreichischer Gewerkschaftsbund', '[{"kategorie": "", "text": "Der ÖGB setzt sich für die Rechte und sozialen Anliegen von Arbeitnehmerinnen und Arbeitnehmern ein und spielt eine zentrale Rolle in der österreichischen [[Sozialpartnerschaft]]"}, {"kategorie": "", "text": "Der ÖGB ist eine Dachorganisation, die aus mehreren Einzelgewerkschaften besteht, die jeweils verschiedene Branchen und Berufsgruppen vertreten. Er wurde 1945 gegründet und ist unabhängig von politischen Parteien"}, {"kategorie": "", "text": "Der ÖGB verhandelt gemeinsam mit den [[Wirtschaftskammern]] die [[Kollektivverträge]] aus, die in Österreich für viele Branchen die Lohn- und Arbeitsbedingungen festlegen. Diese Verträge regeln Mindestlöhne, Arbeitszeiten, Urlaubsansprüche und andere Arbeitsbedingungen und sind rechtlich bindend für die entsprechenden Branchen"}, {"kategorie": "", "text": "Der ÖGB bietet seinen Mitgliedern Unterstützung bei arbeitsrechtlichen Anliegen und Problemen am Arbeitsplatz. Dazu gehören Beratungen in arbeitsrechtlichen Fragen, Unterstützung bei Konflikten mit Arbeitgebern und Vertretung bei arbeitsrechtlichen Verfahren"}, {"kategorie": "", "text": "Der ÖGB bietet Bildungsangebote und Schulungen für Arbeitnehmer an, um deren berufliche und persönliche Entwicklung zu fördern. Er betreibt Bildungsinstitute und führt Seminare zu Arbeitsrecht, Sozialpolitik und beruflicher Weiterbildung durch"}, {"kategorie": "", "text": "Der Österreichische Gewerkschaftsbund ist als Dachverband strukturiert und besteht aus sieben Einzelgewerkschaften, die jeweils spezifische Branchen und Berufsgruppen vertreten, darunter:  (i) Gewerkschaft der Privatangestellten (GPA): für Angestellte und Beschäftigte in der Privatwirtschaft;  (ii) PRO-GE: Produktionsgewerkschaft für Industrie- und Produktionsberufe;  (iii) VIDA: für Transport, Tourismus und soziale Berufe;  (iv) YOUNION: für Gemeindebedienstete und Beschäftigte im Kunst- und Kulturbereich;  (v) GÖD: Gewerkschaft Öffentlicher Dienst;  (vi) DJU: für Journalisten und Mitarbeiter in der Medienbranche;  (vii) VÖGB: als Vertretung für übergeordnete gewerkschaftliche Interessen"}, {"kategorie": "", "text": "Die Delegierten der Einzelgewerkschaften wählen die Führung des ÖGB, darunter den Präsidenten und den Bundesvorstand, der die Richtlinien der gewerkschaftlichen Arbeit festlegt. Der ÖGB ist föderal organisiert und hat regionale Büros in allen Bundesländern, um Arbeitnehmer vor Ort zu unterstützen"}, {"kategorie": "", "text": "Der ÖGB finanziert sich über Mitgliedsbeiträge, die von den Mitgliedern gezahlt werden. Die Mitgliedschaft im ÖGB ist freiwillig, und die Mitglieder haben Zugang zu den vielfältigen Serviceleistungen, Bildungsangeboten und rechtlichen Unterstützungsleistungen der Gewerkschaft."}]'::jsonb, ''),
  ('gemeinde-wiin', 'Gemeinde Wiin', '', '', '', '', 'Gemeinde Wien', '[{"kategorie": "allg.", "text": "\"Verwaltungseinheit, welche die Funktionen einer [[Gemeinde]], einer [[Stadt]] und eines [[Bundeslands]] vereint\""}, {"kategorie": "", "text": "Aufgrund dieser einzigartigen Stellung übernimmt die Gemeinde Wien sowohl Aufgaben der kommunalen [[Selbstverwaltung]] als auch die eines Bundeslands und einer [[Bezirksverwaltungsbehörde]]"}, {"kategorie": "", "text": "Doppelfunktion als [[Gemeinde]] und [[Bundesland]]: Wien ist sowohl eine [[Stadtgemeinde]] als auch ein [[Bundesland]]. Das bedeutet, dass die Stadt Wien eigene Landesgesetze erlassen kann, ähnlich wie die anderen österreichischen Bundesländer, und zugleich alle kommunalen Aufgaben einer Gemeinde übernimmt. Sie agiert damit als eine Art Stadtstaat innerhalb Österreichs"}, {"kategorie": "", "text": "[[Statutarstadt]]: Als Statutarstadt hat Wien das Recht, Aufgaben der Bezirksverwaltung und andere Verwaltungsangelegenheiten eigenständig zu regeln, ohne eine zusätzliche Bezirksebene wie z.B. eine [[Bezirkshauptmannschaft]]"}, {"kategorie": "", "text": "Wien ist in 23 Bezirke unterteilt, die jedoch keine eigenständigen Gemeinden sind. Sie besitzen jeweils ein eigenes [[Bezirksamt]] und eine Bezirksvertretung, die lokale Anliegen verwaltet und als Ansprechpartner für die Bürger fungiert. Die Bezirke sind vor allem Verwaltungseinheiten und haben keine eigene gesetzgebende Gewalt"}, {"kategorie": "", "text": "Der [[Gemeinderat]] von Wien übernimmt die kommunalen Aufgaben, während der [[Landtag]] von Wien die Landesaufgaben wahrnimmt. Beide Gremien sind personell identisch, aber in unterschiedlichen Funktionen tätig. Sie werden alle fünf Jahre in einer gemeinsamen Wahl bestimmt"}, {"kategorie": "", "text": "Der [[Bürgermeister]] von Wien ist gleichzeitig [[Landeshauptmann]] und repräsentiert sowohl die [[Gemeinde]] als auch das [[Bundesland]]. Er ist das Oberhaupt der Stadtverwaltung und leitet die Stadtregierung, die in Wien à„Stadtsenat und [[Landesregierung]]“ genannt wird"}, {"kategorie": "", "text": "Der [[Magistrat]] der Stadt Wien ist die zentrale Verwaltungsbehörde der Stadt Wien und übernimmt die Aufgaben, die in anderen Städten auf Bezirks- oder Gemeindeebene angesiedelt sind. Der Magistrat ist in zahlreiche Magistratsabteilungen (MAs) gegliedert, die jeweils für spezifische Aufgabenbereiche zuständig sind, wie etwa Soziales (MA 40), Bauwesen (MA 37), und Müllentsorgung (MA 48)"}, {"kategorie": "", "text": "Die Gemeinde Wien ist für alle klassischen kommunalen Aufgaben verantwortlich, wie die Müllentsorgung, die Wasserversorgung, den öffentlichen Nahverkehr, die Instandhaltung von Straßen und Grünflächen sowie das Bildungswesen und die Gesundheitsversorgung"}, {"kategorie": "", "text": "Als Bundesland hat Wien eine eigene Landesgesetzgebung. Der [[Landtag]] von Wien erlässt Gesetze für das Bundesland, etwa in den Bereichen Bauordnung, Naturschutz, Jugendwohlfahrt und Wohnbauförderung"}, {"kategorie": "", "text": "Die Gemeinde Wien bietet umfassende soziale Dienste, darunter Sozialhilfe, Wohnbeihilfe, Jugendhilfe, Pflegeeinrichtungen und zahlreiche Gesundheitsdienstleistungen. Die Stadt betreibt zudem ein breites Netz an Krankenhäusern und sozialen Einrichtungen"}, {"kategorie": "", "text": "Der öffentliche Verkehr in Wien wird von der Gemeinde verwaltet und organisiert. Die [[Wiener]] Linien, ein Unternehmen im Besitz der Stadt Wien, betreiben das öffentliche Verkehrsnetz der Stadt. Auch die Planung und Pflege der Verkehrs- und Straßeninfrastruktur gehören zu den Aufgaben der Gemeinde"}, {"kategorie": "", "text": "Wien ist bekannt für seine kulturellen Einrichtungen und fördert Kunst und Kultur. Die Gemeinde betreibt Museen, Theater und zahlreiche Freizeitmöglichkeiten und fördert Veranstaltungen, die zur kulturellen Identität und Lebensqualität der Stadt beitragen (siehe [[Wiener Festwochen]] sowie [[Donauinselfest]])."}]'::jsonb, ''),
  ('magistratisches-beziaksaumt', 'Magistratisches Beziaksaumt', '', '', '', '', 'Magistratisches Bezirksamt', '[{"kategorie": "allg.", "text": "\"lokale Verwaltungsbehörde für jeden der 23 Bezirke der [[Stadt]] Wien\""}, {"kategorie": "", "text": "Anders als in den übrigen österreichischen [[Bundesländern]], wo die Verwaltung auf der Bezirksebene durch [[Bezirkshauptmannschaften]] erfolgt, übernimmt in Wien der [[Magistrat]] der Stadtverwaltung diese Aufgabe"}, {"kategorie": "", "text": "Die Magistratischen Bezirksämter sind Abteilungen des Magistrats der Stadt Wien und haben die Funktion einer lokalen Behörde, die für Verwaltungs- und Ordnungsaufgaben im jeweiligen Bezirk zuständig ist"}, {"kategorie": "", "text": "Hauptaufgaben eines Magistratischen Bezirksamts:  (i) Bürgerdienste: Ausstellung von Dokumenten wie Meldebestätigungen, Reisepässen, und Personalausweisen;  (ii) Gewerbewesen: Bearbeitung von Gewerbeanmeldungen und -abmeldungen sowie Aufsicht über lokale Unternehmen;  (iii) Bauangelegenheiten: Erteilung von Baubewilligungen, Kontrolle von Bauprojekten und Einhaltung der Bauordnung;  (iv) Gesundheitswesen: Durchführung von Gesundheits- und Hygienekontrollen, Betreuung des öffentlichen Gesundheitsdienstes;  (v) Jugend- und Sozialwesen: Unterstützung in sozialen und jugendrechtlichen Angelegenheiten, wie z. B. Familienberatung und Jugendamt-Dienste;  (vi) Ordnung und Sicherheit: Aufgaben der Verwaltungspolizei, darunter Kontrolle der Einhaltung von Gesetzen und Vorschriften"}, {"kategorie": "", "text": "Die Magistratischen Bezirksämter in Wien bieten somit Bürger*innen eine zentrale Anlaufstelle für viele ihrer administrativen Anliegen und spielen eine wesentliche Rolle in der dezentralen Struktur der [[Wiener]] Stadtverwaltung."}]'::jsonb, ''),
  ('wiina-schdodtvawoitung', 'Wiina Schdodtvawoitung', '', '', '', '', 'Wiener Stadtverwaltung', '[{"kategorie": "allg.", "text": "\"Verwaltungsorganisation der [[Stadt]] Wien, welche die öffentliche Verwaltung der Stadt sowie die Umsetzung von Aufgaben auf Gemeinde- und Landesebene übernimmt\""}, {"kategorie": "", "text": "Wien hat als einzige Stadt in Österreich eine Sonderstellung: Sie ist sowohl eine Stadt als auch ein [[Bundesland]]. Dadurch agiert die Stadtverwaltung nicht nur als Kommunalverwaltung, sondern auch als [[Landesregierung]]"}, {"kategorie": "", "text": "Struktur der Wiener Stadtverwaltung:  (i) Der [[Wiener]] Gemeinderat: Er ist das höchste Organ der Stadt und fungiert gleichzeitig als Landtag des Bundeslandes Wien. Er beschließt Gesetze auf Landesebene und Verordnungen sowie das Stadtbudget;  (ii) Der [[Wiener]] Bürgermeister: Der Bürgermeister ist sowohl das Stadtoberhaupt als auch [[Landeshauptmann]] von Wien. Er leitet die [[Stadtregierung]], vertritt Wien nach außen und ist verantwortlich für die Umsetzung der politischen Beschlüsse des Gemeinderats;  (iii) Der [[Stadtsenat]]: Er besteht aus dem Bürgermeister und den [[Stadträten]] und übernimmt exekutive Aufgaben der Stadtverwaltung. Der Stadtsenat entspricht auch der Landesregierung in anderen Bundesländern und kümmert sich um ressortspezifische Verwaltungsbereiche;  (iv) Die [[Magistratsdirektion]]: Als zentrale Verwaltungsstelle ist die Magistratsdirektion für die Koordination der städtischen Behörden und Abteilungen verantwortlich. Sie unterstützt den Bürgermeister und den Stadtsenat in administrativen Aufgaben und überwacht die Umsetzung von Entscheidungen;  (v) Die Magistratsabteilungen (MA): Die Stadtverwaltung ist in verschiedene Magistratsabteilungen unterteilt, die jeweils spezifische Verwaltungsaufgaben übernehmen, wie z. B. Stadtplanung (MA 18), Gesundheitsdienste (MA 15) oder Bildung und Jugend (MA 13)"}, {"kategorie": "", "text": "[[Magistratische]] Bezirksämter: Die 23 Wiener Bezirke haben eigene Magistratische Bezirksämter, die lokale Verwaltungsaufgaben wahrnehmen. Sie dienen als Anlaufstelle für die Bürger*innen in administrativen und ordnungsrechtlichen Angelegenheiten"}, {"kategorie": "", "text": "Hauptaufgaben der Wiener Stadtverwaltung:  (i) Infrastruktur und Stadtentwicklung: Planung und Entwicklung der städtischen Infrastruktur wie Verkehrssysteme, Straßenbau und Stadtgestaltung;  (ii) Öffentliche Dienstleistungen: Bereitstellung von Gesundheitsdiensten, Sozialdiensten, Bildungs- und Jugendeinrichtungen;  (iii) Ordnung und Sicherheit: Einhaltung und Durchsetzung städtischer Vorschriften und Gesetze, Verwaltung der [[Polizei]] in Zusammenarbeit mit der Bundespolizei;  (iv) Umwelt und Energie: Maßnahmen zur Stadtbegrünung, Umweltschutz und Förderung nachhaltiger Energiequellen;  (v) Wirtschaftsförderung und Kultur: Unterstützung der lokalen Wirtschaft, Organisation kultureller Veranstaltungen und Förderung des Tourismus"}, {"kategorie": "", "text": "Die Wiener Stadtverwaltung ist somit eine komplexe Struktur, die sowohl die Aufgaben einer Stadtverwaltung als auch einer Landesregierung erfüllt und alle Bereiche des öffentlichen Lebens in Wien steuert und verwaltet."}]'::jsonb, ''),
  ('wiina-magistratsdirektion', 'Wiina Magistratsdirektion', '', '', '', '', 'Wiener Magistratsdirektion', '[{"kategorie": "allg.", "text": "\"zentrales Verwaltungsorgan der [[Stadt]] Wien, welches die Arbeit der verschiedenen [[Magistratsabteilungen]] und Dienststellen koordiniert\""}, {"kategorie": "", "text": "Die Magistratsdirektion fungiert als die oberste Leitungs- und Koordinationsstelle innerhalb der [[Wiener]] Stadtverwaltung und ist direkt dem [[Bürgermeister]] unterstellt"}, {"kategorie": "", "text": "Die Magistratsdirektion unterstützt die politischen Organe der Stadt bei der Umsetzung ihrer Entscheidungen und stellt sicher, dass die Verwaltungsaufgaben effizient und ordnungsgemäß ausgeführt werden"}, {"kategorie": "", "text": "Hauptaufgaben der Wiener Magistratsdirektion:  (i) Koordination und Leitung: Sie sorgt für die reibungslose Zusammenarbeit zwischen den einzelnen Magistratsabteilungen und den Magistratischen Bezirksämtern. Die Magistratsdirektion stellt sicher, dass die Abläufe einheitlich und effizient gestaltet sind;  (ii) Beratung und Unterstützung: Die Magistratsdirektion unterstützt den Bürgermeister, den [[Stadtsenat]] und die politischen Gremien der Stadt Wien in administrativen Angelegenheiten. Sie berät diese in rechtlichen, strategischen und operativen Fragen;  (iii) Strategische Planung und Steuerung: Die Magistratsdirektion entwickelt und überwacht die strategische Planung der Stadtverwaltung, legt langfristige Ziele fest und sorgt für deren Umsetzung. Dies umfasst auch die Stadtentwicklungsplanung, die Personalplanung und die Finanzsteuerung;  (iv) Controlling und Qualitätsmanagement: Sie stellt sicher, dass die Qualität der städtischen Dienstleistungen und Projekte den festgelegten Standards entspricht. Durch ein umfassendes Controlling überwacht die Magistratsdirektion die Effizienz und Effektivität der städtischen Verwaltungsarbeit;  (v) Personalmanagement: Die Magistratsdirektion ist verantwortlich für das zentrale Personalwesen der Stadt Wien, einschließlich Personalplanung, Ausbildung und Personalentwicklung für alle städtischen Bediensteten;  (vi) Kommunikation und Öffentlichkeitsarbeit: Sie koordiniert die Kommunikationsstrategien der Stadt Wien und sorgt für den transparenten Informationsfluss gegenüber der Öffentlichkeit;  (vii) IT und Digitalisierung: Die Magistratsdirektion spielt eine Schlüsselrolle bei der Digitalisierung der Wiener Stadtverwaltung und entwickelt die IT-Infrastruktur weiter, um die digitalen Services für Bürgerinnen und Mitarbeiterinnen zu verbessern"}, {"kategorie": "", "text": "Die Magistratsdirektion gliedert sich in verschiedene Geschäftsgruppen, die jeweils spezifische Verwaltungsbereiche abdecken, darunter Personal, Finanzen, strategische Planung und Controlling, Rechtsangelegenheiten und Kommunikation. Jede Geschäftsgruppe wird von einem Geschäftsgruppenleiter geführt, und die Gesamtheit der Abteilungen wird vom Magistratsdirektor geleitet, der als höchste Verwaltungsposition in der Wiener Stadtverwaltung fungiert"}, {"kategorie": "", "text": "Die Wiener Magistratsdirektion bildet somit das organisatorische Rückgrat der Stadtverwaltung und sorgt dafür, dass die politischen und administrativen Prozesse effizient und im Einklang mit den gesetzlichen Vorgaben ablaufen."}]'::jsonb, ''),
  ('wiina-magistratsobtaeulungan', 'Wiina Magistratsobtäulungan', '', '', '', '', 'Wiener Magistratsabteilungen', '[{"kategorie": "", "text": "Jede Magistratsabteilung ist für bestimmte Aufgaben- und Fachbereiche zuständig und übernimmt administrative und operative Funktionen, um die städtischen Dienstleistungen für die Bürger*innen sicherzustellen. Diese Struktur ermöglicht eine klare Aufgabenverteilung und eine effiziente Verwaltung in den vielfältigen Bereichen des öffentlichen Lebens in Wien"}, {"kategorie": "", "text": "Die Magistratsabteilungen sind nummeriert und thematisch gegliedert, wobei jede Abteilung einen spezifischen Zuständigkeitsbereich abdeckt. Zu den bekanntesten Magistratsabteilungen gehören zum Beispiel:  (i) MA 01 – Wiener Digitales: Verantwortlich für die Digitalisierung der Stadt und die Entwicklung von IT-Infrastrukturen;  (ii) MA 13 – Bildung und Jugend: Zuständig für Bildungsangebote, Kinderbetreuungseinrichtungen und Jugendprogramme;  (iii) MA 15 – Gesundheitsdienst der Stadt Wien: Übernimmt Aufgaben im öffentlichen Gesundheitswesen, wie Gesundheitsprävention, Hygienekontrollen und medizinische Betreuung;  (iv) MA 18 – Stadtentwicklung und Stadtplanung: Plant die bauliche und infrastrukturelle Entwicklung der Stadt und entwirft Strategien für nachhaltiges Wachstum;  (v) MA 48 – Abfallwirtschaft, Straßenreinigung und Fuhrpark: Verwaltet die städtische Abfallentsorgung, Straßenreinigung und den Fuhrpark der Stadt"}, {"kategorie": "", "text": "Hauptaufgaben der Magistratsabteilungen:  (i) Umsetzung von Gesetzen und Verordnungen: Jede Abteilung ist für die Umsetzung und Überwachung der Einhaltung städtischer und landesweiter Gesetze sowie Verordnungen in ihrem jeweiligen Fachgebiet verantwortlich;  (ii) Service und Dienstleistungen für Bürger*innen: Die Magistratsabteilungen bieten zahlreiche Dienstleistungen an, wie z. B. Anträge für Baubewilligungen, soziale Unterstützung, Gesundheitsberatung, Wohnservices und Umweltberatung;  (iii) Stadtentwicklung und Infrastruktur: Abteilungen wie die MA 18 und MA 28 (Straßenverwaltung und Straßenbau) tragen zur Planung und Entwicklung der städtischen Infrastruktur bei und fördern die nachhaltige Stadtentwicklung;  (iv) Gesundheit und Soziales: Abteilungen wie die MA 15 und MA 40 (Soziales, Sozial- und Gesundheitsrecht) kümmern sich um die öffentliche Gesundheit, soziale Unterstützung und betreuen soziale Einrichtungen und Gesundheitsdienste;  (v) Umwelt und Sicherheit: Abteilungen wie die MA 22 (Umweltschutz) arbeiten an Maßnahmen für Umweltschutz, Nachhaltigkeit und Sicherheitsvorkehrungen in Wien;  (vi) Kultur und Bildung: Die MA 7 (Kultur) und MA 13 fördern kulturelle Aktivitäten, organisieren Veranstaltungen und unterstützen Bildungsprogramme für verschiedene Altersgruppen"}, {"kategorie": "", "text": "Rolle der Magistratsabteilungen in der Wiener Stadtverwaltung: Die Wiener Magistratsabteilungen ermöglichen eine dezentralisierte und effiziente Verwaltung, die sich gezielt um verschiedene Aufgabenbereiche kümmert und dadurch die Qualität und Erreichbarkeit der städtischen Dienstleistungen gewährleistet. Jede Abteilung hat eigene Anlaufstellen für Bürger*innen und stellt Ressourcen zur Verfügung, die auf die spezifischen Bedürfnisse der Bevölkerung und der Stadtstruktur abgestimmt sind."}]'::jsonb, ''),
  ('wiina-gemeindevawoitung', 'Wiina Gemeindevawoitung', '', '', '', '', 'Wiener Gemeindeverwaltung', '[{"kategorie": "allg.", "text": "\"Verwaltungsstruktur der [[Stadt]] Wien, die sich um die lokalen Angelegenheiten der Stadt kümmert\""}, {"kategorie": "", "text": "Da Wien sowohl als [[Gemeinde]] als auch als [[Bundesland]] organisiert ist, übernimmt die Wiener Gemeindeverwaltung Aufgaben, die in anderen österreichischen Städten von der [[Stadtverwaltung]] und auf Landesebene von der [[Landesregierung]] erfüllt werden. Die Gemeindeverwaltung ist somit eine Doppelverwaltung und hat sowohl Gemeinde- als auch Landeskompetenzen"}, {"kategorie": "", "text": "Struktur der Wiener Gemeindeverwaltung:  (i) Der [[Wiener]] Gemeinderat: Der Gemeinderat ist das gesetzgebende Organ der Stadt und entscheidet über alle wesentlichen Angelegenheiten der Stadt Wien. Er fungiert gleichzeitig als [[Landtag]] des Bundeslandes Wien und verabschiedet [[Gesetze]] und [[Verordnungen]] sowie das Budget der Stadt;  (ii) Der [[Bürgermeister]] und der [[Stadtsenat]]: Der Bürgermeister von Wien ist das Stadtoberhaupt und zugleich [[Landeshauptmann]]. Unterstützt wird er durch den [[Stadtsenat]], dem die [[Stadträte]] angehören, welche ihrerseits für verschiedene Ressorts verantwortlich sind. Der Stadtsenat übernimmt die exekutive Führung der Stadtverwaltung und steuert die Umsetzung der politischen Entscheidungen;  (iii) Die [[Magistratsdirektion]]: Die Magistratsdirektion ist das zentrale Steuerungsorgan der Wiener Gemeindeverwaltung und koordiniert die einzelnen Verwaltungsbereiche und [[Magistratsabteilungen]]. Sie unterstützt den Bürgermeister und den Stadtsenat und sorgt für eine einheitliche Verwaltung;  (iv) Die [[Magistratsabteilungen]] (MA): Die Wiener Gemeindeverwaltung ist in zahlreiche Magistratsabteilungen unterteilt, die jeweils spezifische Aufgabenbereiche wie Bildung, Gesundheit, Stadtplanung, Umweltschutz oder Kultur abdecken. Jede Abteilung ist für bestimmte Verwaltungsaufgaben und Dienstleistungen verantwortlich;  (v) [[Magistratische]] Bezirksämter: In den 23 Wiener Bezirken sind die Magistratischen Bezirksämter lokale Anlaufstellen für die Bürger*innen und übernehmen verschiedene Verwaltungsaufgaben auf Bezirksebene, wie die Ausstellung von Meldebescheinigungen, Gewerbegenehmigungen oder die Bearbeitung sozialer Anliegen"}, {"kategorie": "", "text": "Hauptaufgaben der Wiener Gemeindeverwaltung:  (i) Kommunale Dienstleistungen: Bereitstellung und Verwaltung von Dienstleistungen wie Müllentsorgung, Wasser- und Energieversorgung, Gesundheitsdienste und öffentliche Verkehrsmittel;  (ii) Bau und Stadtentwicklung: Planung und Umsetzung städtischer Bauprojekte, Wohnbaupolitik und die Förderung nachhaltiger Stadtentwicklung;  (iii) Soziale Unterstützung und Bildung: Bereitstellung sozialer Hilfen, Unterstützung von Bildungseinrichtungen und Förderung von Familien- und Jugendprogrammen;  (iv) Kultur- und Freizeitangebote: Förderung kultureller Projekte, Unterstützung von Museen, Theatern und anderen kulturellen Einrichtungen sowie Verwaltung von öffentlichen Parks und Freizeitanlagen;  (v) Sicherheit und Ordnung: Zusammenarbeit mit der Polizei zur Gewährleistung der öffentlichen Sicherheit, Kontrolle und Durchsetzung von städtischen Vorschriften und Bauordnungen"}, {"kategorie": "", "text": "Die Wiener Gemeindeverwaltung ist somit eine komplexe und vielschichtige Organisation, die sowohl städtische als auch landesweite Aufgaben erfüllt. Sie ist darauf ausgerichtet, die Lebensqualität in Wien zu fördern, die Verwaltung effizient zu gestalten und den Bürger*innen eine breite Palette an Dienstleistungen zur Verfügung zu stellen."}]'::jsonb, ''),
  ('koeapaschoft-oeffentlichn-rechts', 'Köapaschoft öffentlichn Rechts', '', '', '', '', 'Körperschaft öffentlichen Rechts', '[{"kategorie": "allg.", "text": "\"juristische Person, die staatliche Aufgaben erfüllt und bestimmte hoheitliche Rechte besitzt, dabei jedoch eine rechtlich selbstständige Einheit bleibt\""}, {"kategorie": "", "text": "Sie wird durch ein Gesetz oder einen Verwaltungsakt geschaffen und ist dem öffentlichen Recht unterstellt"}, {"kategorie": "", "text": "Körperschaften öffentlichen Rechts können staatliche Befugnisse ausüben, etwa die Erhebung von Gebühren und die Erteilung von Genehmigungen, und erfüllen häufig Aufgaben in Bereichen wie Verwaltung, Bildung, Sozialwesen oder Wirtschaft. Sie stehen damit zwischen staatlichen Institutionen und privaten Organisationen und agieren als öffentlich-rechtliche Einrichtungen mit einem spezifischen Aufgabenbereich"}, {"kategorie": "", "text": "Merkmale einer Körperschaft öffentlichen Rechts:  (i) Hoheitliche Befugnisse: Körperschaften öffentlichen Rechts dürfen hoheitliche Aufgaben wahrnehmen, z. B. die Festsetzung von Gebühren, Erlass von Satzungen oder die Erteilung von Zulassungen und Genehmigungen;  (ii) Mitgliedschaft: Die Mitgliedschaft in einer Körperschaft öffentlichen Rechts kann entweder freiwillig sein, wie bei Kammern, oder auch verpflichtend, z. B. für bestimmte Berufsgruppen. Bei Pflichtmitgliedschaft kann die Körperschaft Mitgliedsbeiträge erheben;  (iii) Aufgaben und Funktion: Körperschaften öffentlichen Rechts übernehmen Aufgaben im Interesse des Gemeinwohls und entlasten staatliche Behörden, indem sie Verwaltungsaufgaben oder Dienstleistungen in speziellen Bereichen übernehmen;  (iv) Selbstverwaltung und Autonomie: Sie haben in ihrem Aufgabenbereich eine begrenzte Autonomie und verwalten sich weitgehend selbstständig, unterliegen aber meist der Aufsicht durch staatliche Stellen"}, {"kategorie": "", "text": "Beispiele für Körperschaften öffentlichen Rechts:  (i) Kammern: Berufsvertretungen wie die [[Wirtschaftskammer]], Ärztekammer oder [[Arbeiterkammer]]. Diese vertreten die Interessen ihrer Mitglieder und regulieren Berufszugänge, Ausbildungsstandards und bieten Beratung;  (ii) Universitäten: Öffentliche Universitäten sind eigenständige Körperschaften öffentlichen Rechts und verwalten sich selbst, insbesondere in akademischen Angelegenheiten, Prüfungsordnungen und Forschung;  (iii) [[Sozialversicherungsträger]]: Die Träger der Sozialversicherung (z. B. die [[Österreichische]] Gesundheitskasse) verwalten die Kranken- und Pensionsversicherung und erheben Beiträge;  (iv) Rundfunkanstalten: In einigen Ländern sind Rundfunkanstalten, die im öffentlichen Interesse arbeiten, Körperschaften öffentlichen Rechts"}, {"kategorie": "", "text": "Vorteile von Körperschaften öffentlichen Rechts:  (i) Nähe zum Bürger: Sie können auf die Bedürfnisse der Bevölkerung in speziellen Bereichen gezielt eingehen;  (ii) Flexibilität und Spezialisierung: Die Selbstverwaltung erlaubt eine spezialisierte und flexible Aufgabenwahrnehmung;  (iii) Entlastung des Staates: Durch ihre [[Selbstverwaltung]] entlasten sie die staatliche Verwaltung in spezifischen Bereichen und fördern eine dezentrale Aufgabenverteilung"}, {"kategorie": "", "text": "Körperschaften öffentlichen Rechts leisten somit einen wichtigen Beitrag zur Erfüllung staatlicher Aufgaben und tragen durch ihre selbstverwaltete Struktur zur öffentlichen Verwaltung und zum Gemeinwohl bei."}]'::jsonb, '')
